    금천보도자료예시문버튼 = 버튼(지역프레임, 100, 300, '아이콘\\지자체탭\\금천\\금천보도자료예시문.PNG', (lambda : 기본.문장('서울 금천구는 27일 \'충주시 홍보맨\' 김선태 주무관을 초청해 직원 혁신 역량강화 교육을 진행한다고 25일 밝혔다.\r\n금천구는 김 주무관의 사례로 직원들이 혁신행정을 펼칠 수 있는 조직문화와 일하는 방식은 무엇인지에 대해 알아보는 시간을 갖고자 교육을 준비했다.\r\n김 주무관은 \'충주시 유튜브 이야기\'를 주제로 자신이 경험하고 시도했던 다양한 홍보 사례들을 소개하며 일하는 방식 개선, 사고방식 전환의 노하우를 직원들에게 전달할 예정이다.\r\n금천구는 직원의 자발적인 참여와 호응을 이끌어 내기 위해 공감할 수 있고 흥미를 느낄 수 있는 강사를 초빙해 직원들의 혁신역량을 제고해오고 있다. 지난해에는 최신 트렌드에 발맞춘 챗 GPT 활용 교육과 조직문화 진단 워크숍을 운영했다.\r\n조직문화 개선도 꾸준히 시도 중이다. 2020년부터 직원 전용 익명 게시판 \'혁신나눔\'을 운영하며 조직문화 개선에 직원 의견을 적극 반영하고 있다. 2021년부터는 \'시보떡 돌리기\'를 폐지하고 시보 해제 직원들에게 축하의 의미로 꽃바구니, 화분, 텀블러 등을 제공하고 있다.\r\n이 같은 노력으로 행정조직 문화 등을 평가하는 \'2023년 지방자치단체 혁신평가\'에서 전국 자치구 69개 중 10위(상위 15%)를 차지해 우수기관으로 선정됐다.\r\n유성훈 금천구청장은 "정부혁신평가 우수기관이라는 좋은 평가도 받았지만 이에 안주하지 않고 올해는 조직문화 개선에 더욱 박차를 가하고자 한다"며 "관행적인 조직문화를 유연하게 개선하고 활력있게 발전시키기 위해 노력하겠다"고 말했다.')))
