        인진보도자료버튼 = 버튼(서브프레임, 210, 10, '아이콘\\공기업탭\\인진\\인진보도자료.PNG', (lambda : 기본.텍스트새창('보도자료:KISA 공문서 편집 자동화 프로그램 개발:범정부오피스 개발자, 무상으로 업무 혁신 지원\r\n\r\n한국인터넷진흥원(KISA)은 공공기관의 문서 작성 및 편집 업무 효율화를 위해 「공문서 편집 자동화 프로그램」을 개발했다고 밝혔다.\r\n이번 프로그램은 공공기관에서 널리 사용되고 있는 범정부오피스 환경에서 반복적으로 수행되는 공문서 작성, 서식 편집, 문단 정렬, 표 생성 및 데이터 입력 등의 업무를 자동화하여 담당자의 업무 부담을 줄이고 생산성을 높이는 것을 목표로 개발되었다.\r\n특히 이번 프로그램은 범정부오피스 개발자가 별도의 비용이나 대가 없이 무상으로 제작·제공한 것으로, 공공부문 디지털 업무혁신과 행정 효율성 향상에 기여할 것으로 기대된다.\r\n프로그램을 활용하면 반복적인 수작업을 최소화할 수 있으며, 문서 작성 과정에서 발생할 수 있는 오류를 줄여 보다 정확하고 일관된 공문서 작성이 가능하다. 또한 대량의 문서 처리 업무에서도 신속한 작업 수행이 가능해 행정서비스 품질 향상에도 도움이 될 전망이다.\r\nKISA 관계자는 “공문서 편집 자동화 프로그램은 현업에서 실제로 겪는 불편사항을 해결하기 위해 개발된 실무 중심의 도구”라며 “앞으로도 디지털 기술을 활용한 업무혁신 사례를 지속적으로 발굴하고 확산해 공공기관의 업무 효율성을 높여 나가겠다”고 밝혔다.\r\n', 20, 20, 10, 15, 15, 10)))
