    역학유행곡선만들기1버튼 = 버튼(지역프레임, 0, 300, '아이콘\\가이드탭\\역학조사\\역학유행곡선만들기.PNG', (lambda : 기본.역학유행곡선만들기1()))
    역학rror서식버튼 = 버튼(지역프레임, 100, 300, '아이콘\\가이드탭\\역학조사\\역학rror서식.PNG', (lambda : 기본.마크다운응용('제목 : 상대위험도 & 오즈비 서식\r\n\r\n표: 구분 : 질병(+):질병(-)\r\n표: 먹음(+) : 10:2\r\n표: 안 먹음(-):2:10\r\n\r\n네모 : 표안에 커서 넣고 RR&OR계산 클릭\r\n네모 : 입력값이 0이면 0.5로 변환하여 RR, OR을 구하고, p값은 0그대로 계산합니다')))
