def 가이드역학위키창():
    지역프레임 = 우측새탭(창, 50, 0, 700, 900)
    역학위키IgMIgG버튼 = 버튼(지역프레임, 0, 50, '아이콘\\가이드탭\\역학위키\\역학위키IgMIgG.PNG', (lambda : 기본.마크다운응용('제목 : Ig Immunoglobulin 면역항체\r\n\r\n소제목 : 한줄 요약\r\n네모 : IgM : 초기 감염상태\r\n네모 : IgG : 과거력, 만성감염, 예방접종력\r\n네모 : A, E, D : 몰라도 됨\r\n\r\n소제목 : IgM\r\n네모 : Immuno globulin Macroglobulin\r\n동그라미 : 크기가 커서 Macroglobulin\r\n네모 : 항원(주로 바이러스)에 노출되면 가장 먼저 생성됨\r\n네모 : 최근에 감염되었음을 의미하며 시간이 지나면 IgM수치가 감소함\r\n\r\n소제목 : IgG\r\n네모 : G는 단순히 구분자, 혈청 면역글로블린 중 75%를 차지하니 대다수의 General을 연상\r\n네모 : IgG 항체는 감염 후 몇 주에서 몇 달 사이에 형성되기 시작\r\n네모 : 장기간 지속되어 면역 보호를 제공함\r\n네모 : 과거의 감염이나, 예방접종으로 인한 면역 상태를 의미\r\n\r\n소제목 : 면역항체\r\n네모 : 면역항체 : Immuno globulin\r\n네모 : 항원(병원체 : 바이러스, 세균, 진균 등)과 결합하여 신체조직이 감염되지 않도록 해주는 친구들\r\n네모 : 항체가 병원체에 결합하면, 병원체는 이동능력이 떨어지고 서로 응집되어서, 옆에 지나가던 포식성 면역세포가 병원체를 냠냠 해버린다.\r\n\r\n소제목 : 몰라도 되는 내용\r\n네모 : IgA : 주로 점막(호흡기, 소화기, 생식기, 요로)에서 바이러스나 세균감염을 방어함\r\n네모 : IgE : 알레르기와 기생충감염\r\n네모 : IgD : 연구가 덜됨(초기면역과 B세포 조절에 관여)\r\n동그라미 : B세포 : 림프구 중 항체를 생성\r\n동그라미 : 림프구 : 백혈구의 일종 T세포, B세포, NK세포')))
    역학위키분리동정버튼 = 버튼(지역프레임, 0, 100, '아이콘\\가이드탭\\역학위키\\역학위키분리동정.PNG', (lambda : 기본.마크다운응용('제목 : 분리동정\r\n\r\n소제목 : 한줄 요약\r\n네모 : 분리동정 : 감염을 일으키는 병원체(세균, 바이러스 등)를 검체에서 분리해내고, 그 종류를 정확히 식별(동정)하는 과정\r\n\r\n소제목 : 분리동정\r\n네모 : 분리(separation) : 分나눌분 離떨어트릴리 : 원하는 균(바이러스)하나만을 선택적으로 키워내는 것(배양)\r\n네모 : 동정(Identification) : 同한가지동 定정할정 : 병원체가 어떤 균인지 바이러스인지 확인하는 것')))
    역학위키PCR버튼 = 버튼(지역프레임, 100, 50, '아이콘\\가이드탭\\역학위키\\역학위키PCR.PNG', (lambda : 기본.마크다운응용('제목 : PCR Polymerase Chain Reaction\r\n\r\n소제목 : 한줄 요약\r\n네모 : PCR : DNA양 늘리는 기술\r\n네모 : reverse transcription-PCR RT-PCR : RNA를 DNA로 변환\r\n네모 : RealTime PCR : 특이 유전자 검출\r\n\r\n소제목 : PCR\r\n네모 : Polymerase Chain Reaction 중합효소 연쇄 반응\r\n네모 : 원하는 유전정보의 양을 늘림\r\n동그라미 : 1 : DNA 한가닥 있음\r\n동그라미 : 2 : 프라이머라는 짧은 가닥의 RNA가 복제 시작점에 붙음\r\n동그라미 : 3 : DNA중합 효소가 프라이머 위치부터 DNA 복사함\r\n동그라미 : 위 1~3 사이클을 N번 반복하면 2^N개 DNA 가닥이 됨\r\n\r\n소제목 : 역전사 PCR\r\n네모 : reverse transcription-PCR RT-PCR\r\n네모 : RNA를 역전사해서 DNA로 만든 후 PCR적용\r\n동그라미 : RNA보다 DNA가 안정적이라 DNA로 변환함\r\n\r\n소제목 : Real Time PCR\r\n네모 : 늘어나는 형광색 유전자를 실시간으로 측정하기\r\n동그라미 : 1 : 타겟 DNA에만 달라붙는 형광 OligoNucleotide 사용\r\n바 : OligoNucleotide : 20개 이하의 핵산으로 이루어진 DNA단일 가닥\r\n동그라미 : 2 : DNA 2배씩 늘리면서 실시간으로 형광강도 측정\r\n동그라미 : CQ : 양성으로 간주 할 수 있는 시점에서 사이클 값CQ(Cycle Quantification)\r\n바 : 특정 DNA양 많으면 CQ값 작음, 특정 DNA양 적으면 CQ값 큼')))
    역학위키엘리사버튼 = 버튼(지역프레임, 200, 50, '아이콘\\가이드탭\\역학위키\\역학위키엘리사.PNG', (lambda : 기본.마크다운응용('제목 : ELISA, 간접면역형광항체법, 웨스턴블롯\r\n\r\n소제목 : 한줄 요약\r\n네모 : ELISA : 항원이 얼마나 많냐?\r\n네모 : 간접면역형광항체법 : 항원의 분포와 위치파악\r\n네모 : 웨스턴블롯 : 크기별로 분리해서 항원이 얼마나 많냐?\r\n\r\n소제목 : 직접 ELISA\r\n네모 : Enzyme-Linked Immunosorbent Assay\r\n동그라미 : 항원이 못 움직이게 고정\r\n동그라미 : 항원과 결합하는 항체를 넣음\r\n동그라미 : 항체와 반응하는 시약같은걸 넣어서 색상 변화를 일으킴\r\n동그라미 : 색상 변화의 정도에 따라 항원의 양을 측정\r\n\r\n소제목 : 간접면역형광항체법 IFA\r\n네모 : Indirect immunoFluorescence Assay\r\n동그라미 : 항원 못 움직이게 고정\r\n동그라미 : 항원과 결합하는 항체를 넣음\r\n동그라미 : 방금 넣은 항체와 결합하는 2차 항체(간접)를 넣음\r\n동그라미 : 2차 항체는 형광물질이라서 항원의 위치와 분포가 표시됨\r\n\r\n소제목 : 웨스턴블롯\r\n네모 : 만든 사람이 서쪽 북쪽 남쪽 동쪽 이렇게 이름 지음, 블롯은 얼룩을 빨아들인다는 뜻임\r\n동그라미 : 전기로 지져서 단백질을 크기별로 분리함\r\n동그라미 : 막에다가 단백질들을 붙임\r\n동그라미 : 항원과 결합하는 항체를 넣음\r\n동그라미 : 방금 넣은 항체와 결합하는 2차 항체를 넣음\r\n동그라미 : 2차 항체와 반응하는 시약을 넣어서 색상 변화나 빛을 일으키고 이걸 측정해서 항원의 양을 파악')))
    역학위키현미경응집법버튼 = 버튼(지역프레임, 300, 50, '아이콘\\가이드탭\\역학위키\\역학위키현미경응집법.PNG', (lambda : 기본.마크다운응용('제목 : 현미경응집법\r\n\r\n소제목 : 한줄 요약\r\n네모 : 현미경응집법 : 항체가 얼마나 있냐?\r\n네모 : 1 대 800 : 항체가 800배 희석된 상태에서도 반응이 있음\r\n\r\n소제목 : 현미경응집법\r\n네모 : microbial agglutination test\r\n동그라미 : 혈액 타액등에서 샘플 채취\r\n동그라미 : 항원을 넣어서 혼합함\r\n동그라미 : 항체가 항원과 결합하면 응집되어 육안으로 관찰할 수 있는 덩어리를 형성함\r\n\r\n소제목 : 희석비율\r\n네모 : 1:800 이상 : 800배 이상 희석해도 유의미한 응집을 보임 : 이는 항체의 농도가 상당히 높다고 판단되며, 병원체에 감염되었거나, 백신 접종을 통해 면역반응이 유도되었다고 판단함 (렙토스피라증)\r\n네모 : 1:200이상 ~ 1:800 미만 : 없다고 하기도 애매해서 추정진단으로 판단함 (렙토스피라증)')))
    역학위키미세응집법버튼 = 버튼(지역프레임, 300, 100, '아이콘\\가이드탭\\역학위키\\역학위키미세응집법.PNG', (lambda : 기본.마크다운응용('제목 : 미세응집법\r\n\r\n소제목 : 한줄 요약\r\n네모 : 미세응집법 : 항원이 항체가 붙은 비드(미세입자)와 결합하면 응집이 발생하며, 이를 통해 항원의 존재 여부 파악\r\n네모 : 1 대 160 : 샘플이 160배 희석된 상태에서도 응집이 보여서 항체가 검출되었다는 의미\r\n\r\n소제목 : 미세응집법\r\n네모 : microagglutination test\r\n동그라미 : 혈액 체액등에서 샘플 채취\r\n동그라미 : 샘플에 특정 항체가 결합된 비드(미세입자)를 추가\r\n동그라미 : 항체가 항원과 결합하면 응집되어 육안으로 관찰할 수 있는 덩어리를 형성함\r\n\r\n소제목 : 희석비율\r\n네모 : 1:160 이상 : 160배 이상 희석해도 유의미한 응집을 보임 : 이는 항체의 농도가 상당히 높다고 판단되며, 병원체에 감염되었음을 추정할 수 있음(브루셀라증)')))
    역학위키후향적코호트버튼 = 버튼(지역프레임, 0, 150, '아이콘\\가이드탭\\역학위키\\역학위키후향적코호트.PNG', (lambda : 기본.마크다운응용('제목 : 조사디자인\r\n\r\n소제목 : 한줄 요약\r\n네모 : 후향적코호트 조사 : 노출된 사람들과 비노출된 사람들의 결과를 비교하는 것이 목적\r\n네모 : Relative Risk 상대위험도 : 노출 집단에서 질병 발생률이 비노출 집단에 비해 몇 배 높은지를 나타냄(확률 개념)\r\n네모 : 사례-대조군조사 : 결과가 발생한 사람들과 발생하지 않은 사람들의 과거 노출 차이를 분석하는 것이 목적\r\n네모 : Odds Ratio 교차비 : 노출 집단에서 질병 발생 위험이 비노출 집단에 비해 몇 배 높은지를 나타냄(비율 개념)\r\n\r\n소제목 : 조사디자인 비교\r\n표:구분 : 후향적코호트 조사 : 사례-대조군조사\r\n표:대상자 선정 :과거 노출 여부에 따라 그룹을 나눔 : 결과 여부에 따라 그룹을 나눔\r\n표:시간적순서 : 노출 → 결과(시간순서 명확): 결과 → 노출(시간순서 불명확)\r\n표: 목적 : 노출이 결과에 미친 영향을 분석 : 결과와 과거 노출 간의 연관성 분석\r\n표 : 지표 : 발생률, 상대위험도(RR):교차비(OR)\r\n표:적합한 상황 : 비교적 흔한 질병 또는 특정 집단 연구 : 드문 질병 연구\r\n표:데이터 출처: 과거기록(노출 및 결과): 과거 기록(노출, 사례군 및 대조군)\r\n\r\n소제목 : 상대위험도(RR, Relative Risk)\r\n네모 : 노출 집단에서 질병 발생률이 비노출 집단에 비해 몇 배 높은지를 나타냄\r\n동그라미 : 공식 : 노출군의 질병 발생률/비노출군의 질병 발생률\r\n동그라미 : 주로 코호트연구에 사용하며, 사례-대조군 연구에는 사용하지 않음(모집단을 임의로 설정하기 때문에 통계적 왜곡 발생)\r\n\r\n소제목 : 교차비(OR, Odds Ration)\r\n네모 : 노출군과 비노출군 간에 질병 발생 가능성(오즈)의 비율을 나타냄\r\n동그라미: 공식 : 노출군의 질병 Odds/비노출군의 질병 Odds\r\n바 : Odds : 사건 발생 수/사건 비발생 수\r\n동그라미: 주로 환자-대조군 연구에서 사용, RR계산이 어려운 경우 OR을 대체 지표로 사용함, 모집단을 임의로 잡아야 하는 경우에 사용함')))
    역학위키항생제개론버튼 = 버튼(지역프레임, 100, 150, '아이콘\\가이드탭\\역학위키\\역학위키항생제개론.PNG', (lambda : 기본.마크다운응용('제목 : 항생제 개론\r\n네모:항생제는 다양한 방식으로 세균을 죽입니다.\r\n\r\n소제목: 세포벽 합성 억제해서 세균을 터트려 죽임\r\n네모:베타락탐 계열\r\n원:세균의 펩티도글리칸 합성을 억제해서 세포벽 형성을 막아서, 세포벽이 있는 세균들을 터트려서 죽입니다\r\n바:페니실린 계: 암피실린, 아목사실린, 옥사실린, 메티실린 등\r\n바:세팔로스포린 계: 세파졸린, 세포탁심, 세프트리악손, 세페핌\r\n바:카바페넴 계: 이피페넴, 메로페넴\r\n바:모노박탐 계: 아즈트레오남\r\n\r\n네모: 글리코펩타이드 계열\r\n원:펩티도글리칸의 전단계 합성을 차단합니다.\r\n바:반코마이신, 테이코플라닌, 다프로마이신\r\n\r\n네모:그람양성 VS 그람음성\r\n원:그람양성: 세포벽 두꺼움\r\n원:그람음성: 세포벽 얇음, 세포벽 바깥에 외막이 존재함\r\n원:세포벽 합성을 억제해서 죽이는 항생제는 그람양성에는 강하지만, 그람음성에는 효과가 약합니다.\r\n원:카바페넴같은 경우 침투력이 좋아서 그람음성도 터트려버립니다.\r\n\r\n\r\n\r\n소제목: 세포막을 터트리거나 이온불균형으로 죽임\r\n네모:폴리믹신 계\r\n원:그람음성균의 외막과, 세포막의 인지질에 결합하여 세포막을 터트림\r\n바:폴리믹신B, 콜리스틴\r\n\r\n네모:레포펩타이드 계\r\n원:세포막 칼슘 의존성 채널을 건드려서 이온 불균형을 유발함\r\n바:다프토마이신\r\n\r\n\r\n\r\n소제목:단백질 합성 방해해서 세균을 고장내버림\r\n네모:아미노글리코사이드 계\r\n원:30s리보솜 고장내서 비정상 단백질 합성\r\n바:겐타마이신, 스트렙토마이신, 토브라마이신, 아믹카신\r\n\r\n네모:테트라사이클린 계\r\n원:30s리보솜 고장내서 번역을 억제함\r\n바:테트라사이클린, 독시사이클린, 미노사이클린\r\n\r\n네모:마크로라이드 계\r\n원:50s리보솜 고장내서 이동을 막음\r\n바:에리스로마이신, 클라리스로마이신, 아지스로마이신\r\n\r\n네모:링코사마이드 계\r\n원:50s리보솜 고장내서 펩티드 결합 형성 억제\r\n바:클린다마이신\r\n\r\n네모:클로람페니콜 계\r\n원:50s리보솜 고장내서 펩티드 결합 형성 억제\r\n바:클로람페니콜\r\n\r\n네모:옥사졸리다논 계\r\n원:50s리보솜 고장내서 개시복합체 형성 억제\r\n바:리네졸리드\r\n\r\n\r\n소제목:DNA, RNA 합성을 억제해서 세균을 고장내버림\r\n네모:퀴놀론 계\r\n원:Topoisomerase 2번 4번을 억제해서 DNA복제를 차단\r\n바:시프로플록사신, 오플록사신, 레보플록사신, 목시플록사신\r\n\r\n네모:리팜피신 계\r\n원:RNA중합효소 차단\r\n바:리팜피신, 리팜부틴, 리팍시민\r\n\r\n네모:니트로이미다졸 계\r\n원:혐기성 환경에서 DNA를 잘라버림\r\n바:메트로니다졸, 티니다졸\r\n\r\n네모:설폰아미드&트리메토프림\r\n원:엽산 합성을 억제해서 DNA합성 억제\r\n바:SMX-TMP(설파메톡사졸+트리메토프림), 박트림')))
    역학위키항바이러스개론버튼 = 버튼(지역프레임, 100, 200, '아이콘\\가이드탭\\역학위키\\역학위키항바이러스개론.PNG', (lambda : 기본.마크다운응용('제목 : 항바이러스제 개론\r\n네모:항바이러스제는 다양한 방식으로 바이러스를 죽입니다.\r\n표:종류:작용:약물\r\n표:DNA/RNA 합성 억제 :\t바이러스 유전자를 복사 못 하게 함\t: 아시클로버, 라미부딘\r\n표:역전사효소 억제\t: HIV가 자기 유전자를 변형하지 못하게 함\t: 지도부딘, 라미부딘\r\n표:프로테아제 억제\t: 바이러스가 자기 몸을 조립 못 하게 함\t: 로피나비르, 다루나비르\r\n표:뉴라미니다제 억제\t: 바이러스가 퍼지지 못하게 막음\t: 타미플루(오셀타미비르)\r\n표:엔도뉴클레아제 억제\t: 바이러스 유전자 복사를 방해\t: 발록사비르\r\n표:융합/침투 억제\t: 바이러스가 세포에 못 들어오게 함\t: 엔푸비르티드, 마라비록\r\n표:직접 작용 항바이러스제\t: 바이러스의 특정 기능을 직접 차단\t: 소포스부비르, 레디파스비르\r\n표:광범위 항바이러스제\t: 여러 바이러스를 한꺼번에 막음\t: 리바비린, 파비피라비르\r\n\r\n\r\n소제목:뉴클레오사이드/뉴클레오타이드 유사체\r\n네모:DNA, RNA 합성 때 짝퉁(유사체)이 들어가서 복제과정을 차단합니다.\r\n네모:바이러스가 스스로 복제하는 데 필요한 "설계도"를 망가뜨리는 약\r\n원:아시클로버(Acyclovir), 발라사이클로버(Valacyclovir), 팜시클로버(Famciclovir) → HSV, VZV\r\n원:간시클로버(Ganciclovir), 발간시클로버(Valganciclovir) → CMV\r\n원:라미부딘(Lamivudine), 엔테카비르(Entecavir), 테노포비르(Tenofovir) → HBV, HIV\r\n원:소포스부비르(Sofosbuvir) → HCV\r\n\r\n소제목:역전사효소 억제제\r\n네모:HIV, HBV와 같은 레트로바이러스의 역전사효소(Reverse Transcriptase)를 억제\r\n네모:바이러스 RNA가 DNA로 전환되는 과정을 막아 복제 차단\r\n네모:HIV 같은 바이러스가 자기 유전자를 변형해서 우리 몸에 숨으려고 하는 걸 방해\r\n원:뉴클레오사이드 역전사효소 억제제 (NRTIs): 라미부딘, 지도부딘, 테노포비르 → HIV, HBV\r\n원:비-뉴클레오사이드 역전사효소 억제제 (NNRTIs): 네비라핀, 에파비렌즈 → HIV\r\n소제목:프로테아제 억제제\r\n네모:바이러스 단백질을 절단하는 프로테아제(Protease) 효소를 억제\r\n네모:바이러스가 제대로 조립되지 못해 감염성 입자가 생성되지 않음\r\n네모:바이러스가 자기 몸을 조립하는 데 필요한 단백질을 자르지 못하게 함\r\n원:HIV: 로피나비르(Lopinavir), 리토나비르(Ritonavir), 다루나비르(Darunavir)\r\n원:HCV: 글레카프레비르(Glecaprevir), 보세프레비르(Boceprevir)\r\n\r\n소제목:뉴라미니다제 억제제\r\n네모:바이러스가 새로운 세포를 감염시키지 못하도록 함\r\n네모:인플루엔자 바이러스가 다른 세포로 퍼지는 걸 막아서 확산을 차단\r\n원:오셀타미비르(Oseltamivir, 타미플루)\r\n원:자나미비르(Zanamivir)\r\n원:페라미비르(Peramivir)\r\n\r\n소제목:캡-의존적 엔도뉴클레아제 억제제\r\n네모:바이러스가 숙주 세포의 mRNA 캡을 이용하는 과정을 억제\r\n네모:바이러스의 전사를 방해하여 단백질 합성을 막음\r\n네모:바이러스가 자기 설계도를 복사하려고 하면 가위로 잘라버리는 약\r\n원:발록사비르 마르복실(Baloxavir Marboxil, 조플루자) → 인플루엔자\r\n\r\n소제목:융합 억제제 및 침투 억제제\r\n네모:바이러스가 숙주 세포와 융합하는 것을 차단\r\n네모:바이러스가 숙주 세포에 침입하지 못하도록 막음\r\n네모:바이러스가 문을 열고 들어오지 못하게 자물쇠를 잠가버리는 약\r\n원:엔푸비르티드(Enfuvirtide) → HIV (바이러스-세포막 융합 차단)\r\n원:마라비록(Maraviroc) → HIV (CCR5 수용체 차단)\r\n\r\n소제목:직접 작용 항바이러스제\r\n네모:HCV 복제 과정의 특정 효소(RdRp, NS3/4A 프로테아제, NS5A 복제 단백질 등)를 직접 억제\r\n네모:바이러스 RNA 복제를 방해\r\n네모:\t바이러스의 특정 기능을 직접 차단\r\n원:소포스부비르(Sofosbuvir) → RNA 중합효소 억제\r\n원:레디파스비르(Ledipasvir), 벨파타스비르(Velpatasvir) → NS5A 억제\r\n원:그라조프레비르(Grazoprevir) → NS3/4A 프로테아제 억제\r\n\r\n소제목:광범위 항바이러스제\r\n네모:여러 바이러스에 작용하는 기전을 가짐\r\n네모:RNA 복제를 방해하거나 돌연변이를 유발하여 바이러스 증식 억제\r\n원:리바비린(Ribavirin) → RNA 돌연변이 유발 (RSV, HCV, Lassa fever 등)\r\n원:파비피라비르(Favipiravir) → RNA 중합효소 억제 (코로나19, 인플루엔자)')))
    역학위키경성하감버튼 = 버튼(지역프레임, 0, 250, '아이콘\\가이드탭\\역학위키\\역학위키경성하감.PNG', (lambda : 기본.마크다운응용('제목 : 경성하감, 편평콘딜롬, 트레포네마, 암시아현미경, 고무종\r\n\r\n소제목 : 간단 요약\r\n네모 : 경성하감 : 딱딱할 경 성질 성 아래쪽 하 피부병 감 딱딱한 성질을 가진 하부 피부질환\r\n네모 : 편평콘딜롬 : 평평한 형태의 생식기 주변 사마귀\r\n네모 : 트레포네마 : 트레포네마 팔리듐이라는 매독의 원인균을 검출하는 검사, 매독에 특이적인 항체를 찾아냄\r\n네모 : 비트레포네마 : 매독이외에도 다른 질환에도 반응할 수 있는 비특이적 검사, 매독이 의심되는 경우 비트레포네마 실시 후 양성나오면 트레포네마 검사함\r\n네모 : 암시아현미경 : amniotic centesis를 암시아라고 함, 임신중에 태아의 유전적질환, 감염, 발달 이상들을 알기위해 양수를 채취하여 현미경으로 분석함\r\n네모 : 고무종 : 고무 같은 형태로 피부 뼈 간 등에 침범함')))
    역학위키p24버튼 = 버튼(지역프레임, 100, 250, '아이콘\\가이드탭\\역학위키\\역학위키p24.PNG', (lambda : 기본.마크다운응용('제목 : p24, 항원중화검사\r\n\r\n소제목 : 간단 요약\r\n네모 : p24 : HIV의 단백질 중 하나\r\n네모 : 항원중화검사 : 환자의 항체가 HIV를 잘 무력화 시키는지 알아보는 검사\r\n\r\n소제목 : p24\r\n네모 : p24 항원은 HIV의 구조적 단백질 중 하나로, HIV의 캡시드(바이러스의 외피를 형성하는 단백질)에서 유래합니다. p는 protein을 의미하고, 24는 이 단백질의 분자량(약 24킬로달톤)을 나타냅니다. p24 항원은 HIV 감염 초기에 나타나며, 바이러스가 체내에 침입한 후 혈액 내에서 빠르게 검출될 수 있습니다.\r\n\r\n소제목 : 항원중화검사\r\n네모 : 환자의 혈청과 HIV 바이러스를 혼합한 후, 특정 세포를 배양합니다. 이때 세포가 감염되면 손상이 발생합니다.\r\n동그라미 : 항체가 HIV를 중화했다면 : 세포가 건강하게 유지되고 손상이 적거나 없습니다. 이는 HIV 감염이 없거나 면역력이 충분하다는 것을 의미합니다.\r\n동그라미 : 항체가 HIV를 중화하지 못했다면 : 세포가 감염되어 손상이 발생합니다. 이는 HIV에 감염되었을 가능성이 있음을 나타냅니다.')))
    역학위키테트라민버튼 = 버튼(지역프레임, 0, 350, '아이콘\\가이드탭\\역학위키\\역학위키테트라민.PNG', (lambda : 기본.마크다운응용("제목 : 테트라민\r\n\r\n소제목 : 요약\r\n네모 : 테트라민 : 신경독소로 가열해도 없어지지 않음, 섭취 30분후 어지러움, 구역, 구토, 설사, 시각장애를 일으키며 심하면 급성호흡부전으로 사망하기도 함\r\n동그라미 : 삐뚤이소라(갈색띠매물고둥), 전복소라(관절매물고둥), 참소라(피뿔고둥), 나팔골뱅이(조각매물골뱅이), 털골뱅이, 호리호리털골뱅이, 명주매물고둥 등을 먹을 때는 반으로 갈라 양쪽의 타액선과 내장을 제거하면 식중독을 예방할 수 있음\r\n\r\n소제목 : 자세한 내용\r\n네모 : 식품의약품안전처 보도자료\r\n동그라미 : 소라의 자연독성이 강해지는 가을철에 소라독으로 인한 식중독 예방을 위하여 타액선 및 내장제거 등 조리법 준수 및 섭취 시 주의가 필요합니다.\r\n동그라미 : 일부 육식성 권패류의 타액선(침샘)과 내장에는 자연독소인 테트라민(Tetramine)이 함유되어 있어, 제거하지 않고 섭취할 경우 식중독증상을 일으킬 수 있습니다.\r\n바 : 권패류 : 소라, 고둥, 골뱅이 등과 같은 나사 모양의 껍질을 가진 패류\r\n동그라미 : 주로 섭취 30분 정도 후 두통, 멀미, 구토, 설사, 시각장애등의 식중독 증상이 나타나며 이 경우 즉시 인근 병원을 찾아 치료받아야 합니다.\r\n동그라미 : 테트라민은 가열하여도 제거되지 않기 때문에 삐뚤이소라(갈색띠매물고둥), 털골뱅이류, 전복소라(관절매물고둥), 참소라(피뿔고둥) 등 독성이 있는 권패류는 조리 시 반드시 독소가 있는 타액선(침샘)을 제거해야 하며, 섭취 시에도 타액선 제거 유무를 확인해야 합니다.\r\n\r\n네모 : 일상에서 주의사항\r\n동그라미 : 독성은 개인에 따라 차이가 있지만 1-2개만 먹어도 중독되는 경우가 있으니 섭취를 피해야 한다. 또한 독성 있는 육식성 고둥이 '소라'라는 이름으로 통용되는 경우도 있어, 소라인 줄 알고 먹은 것이 독 있는 고둥일 수도 있다. 따라서 이러한 지식이 없는 일반인의 경우, 고둥이든 소라이든 조리 전에 반드시 타액선을 제거해야 한다. 먹기 전에도 타액선이 있는지 잘 살펴봐야 한다. 또한 증상은 일반적인 어지러움증, 구토, 시야장애 증상과 유사하여, 중독 시 응급실에 와도 테트라민 중독이라고 진단하기 어려운 경우가 있다. 따라서 고둥류 섭취 후 테트라민 중독 증상이 나타나면 응급실에 가서 의사에게 고둥 섭취 사실을 알리는 것이 좋다. 중독 증상이 발생할 수 있는 섭취량에는 개인마다 편차가 있지만, 섭취 이후 증상이 나타나면 지체없이 병원으로 가는 것이 좋다.\r\n\r\n네모 : 독성학\r\n동그라미 : 독성학에서는 테트라민(tetramine)이라고 불리는 테트라메틸암모늄은 매물고둥속(Neptunea) 종류를 섭취한 후에 발생하는 중독과 관련하여 연구되었다. 증상은 다음과 같다. 구역질, 구토, 두통, 현기증, 시야 흐려짐, 일시적 실명, 복시(diplopia), 눈부심(photophobia), 균형감각 상실, 중독 혹은 두드러기(urticaria)가 난 듯한 느낌이 있다. 증상 30분 이내로 발생하지만 몇 시간 후에 완전히 회복된다.\r\n동그라미 : 증상 발생 원인은 대부분 자율신경계(autonomic nervous system) 신경전달이 차단되는 것으로 보지만, 중추 영향(central affect)으로도 설명된다.\r\n동그라미 : 동물연구에서, 매물고둥속 추출물을 쥐나 고양이, 물고기에게 비경구투약할 경우, 골격근에 효과를 미치는 것이 주를 이룬다. 또한 근섬유다발수축, 경련, 균형감각 상실, 운동마비, 마지막엔 호흡 중지가 발생한다.\r\n동그라미 : 사람의 경우 치사량이 체중 1kg당 3–4mg이다.\r\n\r\n네모 : 타액선이 없어 안심하고 먹어도 되는 종류\r\n동그라미 : 뿔소라, 백골뱅이(물레고둥), 흑골뱅이(깊은물레고둥), 위고둥, 큰구슬우렁")))


def 가이드튜토리얼창():
    지역프레임 = 우측새탭(창, 50, 0, 700, 600)
    튜토리얼물건어찌삼버튼 = 버튼(지역프레임, 0, 50, '아이콘\\가이드탭\\튜토리얼\\튜토리얼물건어찌삼.PNG', (lambda : 기본.마크다운응용("제목 : 물건 어찌 삼?\r\n\r\n소제목 : 물품구매의 5단계\r\n네모 : 품의 -> 원인 -> 검수 -> 결의 -> 지급\r\n\r\n동그라미 : 품의 : 물품구매를 팀장, 경리, 과장에게 보고 후 검토 받는 과정 입니다.\r\n바 : 여쭐 품 + 의논할 의 : 상사에게 글로 여쭈어 의논함\r\n바 : 이렇게 돈 써도 되나요? 하고 공문서를 써서 검토하는 단계이며, 검토이기 때문에 품의금액과 지급금액은 다를 수 있습니다.\r\n바 : 관련서류 : 품의공문\r\n\r\n동그라미 : 원인 : 지출의 원인이 되는 계약이나 행위 입니다.\r\n바 : 근원 원 + 인할 인 : 지출을 일으키게 된 근본\r\n바 : 지출원인행위는 계약체결이나 발주 같은거 입니다.\r\n바 : '원인' 행위가 중요한 건 이때부터 지출에 대한 의무가 생기기 때문입니다. 즉, 실제 돈은 나가지 않았어도 원인 행위가 달리는 순간 해당 건에 대한 지출은 배정된 예산에서 빠집니다.\r\n바 : 관련서류 : 계약서, 구매요청서(발주) 등\r\n\r\n동그라미 : 검수 : 물건이나 서비스(용역)가 정상인지 확인합니다.\r\n바 : 검사할 검 + 거둘 수 : 물건 받은 걸 검사함\r\n바 : 물건을 구매했으면 물건이 주문한대로 들어왔는지, 서비스라면 당초 계약한대로 이루어졌는지 확인(검수)하는 단계입니다.\r\n바 : 관련서류 : 물품검수조서, 완료확인서 등\r\n\r\n동그라미 : 결의 : 대가 지급을 결정합니다.\r\n바 : 결단할 결 + 의논할 의 : 대가지급 결정을 의논함\r\n바 : 물품 또는 서비스가 계약대로 이루어졌으니 대가 지급을 결정하는 단계입니다. 이때 중요한 건 자금배정이 되어 있어야합니다.\r\n바 : 관련서류 : 지출 결의서\r\n바 : 예산Budget : 미래의 수입과 지출 계획, 계획 및 승인된 금액\r\n바 : 자금Fund : 실제 사용 가능한 현금, 실제로 집행 가능한 금액\r\n\r\n동그라미 : 지급 : 상대에게 실제 돈이 지급됩니다.\r\n바 : 값 지 + 줄 급 : 돈을 정해진 만큼 줌\r\n바 : 경리 주무관님이 상대에게 돈을 지급합니다. 보통 사업담당자는 결의까지 일을 하기 때문에 건들 일이 없습니다.\r\n바 : 방법 : 계좌이체 등")))
    튜토리얼50미만카드결제버튼 = 버튼(지역프레임, 0, 100, '아이콘\\가이드탭\\튜토리얼\\튜토리얼50미만카드결제.PNG', (lambda : 기본.마크다운응용('제목 : 50만 미만 카드\r\n\r\n네모 : 품의~원인(발주)\r\n동그라미 : 1. 물건을 구매할겁니다.\r\n동그라미 : 2. 업체에 주문을 넣고 물건의 견적 및 시안을 받습니다.\r\n동그라미 : 3. e호조 → 지출관리 → 지출품의 → 지출결재요청(21101)\r\n동그라미 : 4. 공통정보의 제목과 집행내용에 품의공문 제목을 입력합니다.\r\n동그라미 : 5. 예산과목에서 추가 버튼을 눌러서 세부사업명 검색으로 예산과목을 검색합니다.\r\n동그라미 : 6. 품의가능액을 확인 후 품의요청액을 입력합니다.\r\n동그라미 : 7. 결재요청 → 확인 → 기안전송 → 확인 → 확인\r\n동그라미 : 8. 5분정도 기다립니다.(늦으면 30분도 넘게 걸림)\r\n동그라미 : 9. 온나라 → 결재 → 처리할문서 → 연계기안함\r\n동그라미 : 10. 범피스 → 가이드 → 물품구매모음 → 물품구매서식 및 품의공문생성 기능을 활용하여 품의공문작성\r\n동그라미 : 11. 결재라인은 보통 팀장(검토) - 경리(협조) - 과장(전결)\r\n동그라미 : 12. 제품사진이나 시안 혹은 스펙등을 붙임으로 첨부\r\n동그라미 : 13. 품의공문 결재 완료 후 발주 요청\r\n\r\n네모 : 검수~원인행위등록\r\n동그라미 : 14. 물품확인\r\n동그라미 : 15. 범피스 → 가이드 → 물품구매모음 → 물품구매서식 및 필요서류안내, 승낙검수수의계약 기능을 활용하여 필요서류 정리\r\n동그라미 : 16. e호조 → 지출관리 → 지출품의 → 지출품의승인내역등록(21103)\r\n동그라미 : 17. 결재문서번호 검색 → 작성자나 제목으로 조회 → 선택\r\n동그라미 : 18. 사업상세 → 법정/보조/이자/재량은 예산내역 눌러서 확인 후 선택, 승인대상자는 보통 팀장님\r\n\r\n네모 : 품의유형 분기 일반/물품구입\r\n동그라미 : 품의유형에 따라 지출결의서 양식이 달라짐\r\n바 : 물품구입~관급자재 5가지는 계약요청을 할 수 있는 품의유형\r\n바 : 보통 간단한건 일반 사용함\r\n\r\n동그라미 : 19. 품의유형 → 일반\r\n동그라미 : 20. 품의액 → 금액입력 → 금액 입력 후 저장\r\n동그라미 : 21. 제목 옆 카드연계 체크 → 카드사용내역 → 카드번호 선택 → 조회 → 사용한 금액 선택 → 사용자실명(본인이름) → 거래처구분 선택 → 저장 → 계좌검증 → 확인\r\n동그라미 : 22. 관리항목 → 계약대장등록여부 아니오 이미 되어있습니다\r\n동그라미 : 23. 일반상세 → 행추가 → 비고내용에 제목을 넣고 → 요청금액에 품의액 입력\r\n\r\n동그라미 : 19. 품의유형 → 물품구입\r\n동그라미 : 20. 품의액 → 금액입력 → 금액 입력 후 저장\r\n동그라미 : 21. 제목 옆 카드연계 체크 → 카드사용내역 → 카드번호 선택 → 조회 → 사용한 금액 선택 → 사용자실명(본인이름) → 거래처구분 선택 → 저장 → 계좌검증 → 확인\r\n동그라미 : 22. 관리항목 → 계약대장등록여부 N → 납기일자는 물건 받은 날 → 납품예정일자는 보통은 견적일 + 2주 → 납품장소는 창고 또는 본인사무실\r\n동그라미 : 23. 물품상세 → 행추가 → 물품관리번호 검색 → 물품명 대충 맞는걸로... 없는것도 많음 귀찮음 → 물품명, 규격명, 단위명 개, 수량, 단가, 거래자 사업자등록번호 입력, 자체계약 체크\r\n\r\n동그라미 : 24. 첨부문서 → 파일추가 → 15번에서 정리한 서류 첨부\r\n동그라미 : 25. 공유범위 → 실국공개 해놓으면 후임자가 나중에 볼 때 편함\r\n동그라미 : 26. 원인행위등록요청 클릭\r\n\r\n\r\n네모 : 자금배정\r\n동그라미 : 27. e호조 → 자금관리 → 자금배정 → 수시배정요구등록 → 수시배정요구(54201)\r\n동그라미 : 28. 조회 → 사업명검색 → 본인예산 더블클릭\r\n동그라미 : 29. 신규 → 요구사유에 품의공문제목 쓰기 → 요구금액 입력 → 승인대상자 보통은 팀장님 → 저장 → 만들어진 내역 선택 후 승인요청\r\n\r\n네모 : 지출결의\r\n동그라미 : 보통 카드지출의 경우 경리주무관님이 맡아서 하십니다\r\n\r\n네모 : 지급\r\n동그라미 : 보통 경리 주무관님이 처리하심')))
    튜토리얼50미만계좌결제버튼 = 버튼(지역프레임, 0, 150, '아이콘\\가이드탭\\튜토리얼\\튜토리얼50미만계좌결제.PNG', (lambda : 기본.마크다운응용('제목 : 50만 미만 계좌이체\r\n\r\n네모 : 품의~원인(발주)\r\n동그라미 : 1. 물건을 구매할겁니다.\r\n동그라미 : 2. 업체에 주문을 넣고 물건의 견적 및 시안을 받습니다.\r\n동그라미 : 3. e호조 → 지출관리 → 지출품의 → 지출결재요청(21101)\r\n동그라미 : 4. 공통정보의 제목과 집행내용에 품의공문 제목을 입력합니다.\r\n동그라미 : 5. 예산과목에서 추가 버튼을 눌러서 세부사업명 검색으로 예산과목을 검색합니다.\r\n동그라미 : 6. 품의가능액을 확인 후 품의요청액을 입력합니다.\r\n동그라미 : 7. 결재요청 → 확인 → 기안전송 → 확인 → 확인\r\n동그라미 : 8. 5분정도 기다립니다.(늦으면 30분도 넘게 걸림)\r\n동그라미 : 9. 온나라 → 결재 → 처리할문서 → 연계기안함\r\n동그라미 : 10. 범피스 → 가이드 → 물품구매모음 → 물품구매서식 및 품의공문생성 기능을 활용하여 품의공문작성\r\n동그라미 : 11. 결재라인은 보통 팀장(검토) - 경리(협조) - 과장(전결)\r\n동그라미 : 12. 제품사진이나 시안 혹은 스펙등을 붙임으로 첨부\r\n동그라미 : 13. 품의공문 결재 완료 후 발주 요청\r\n\r\n네모 : 검수~원인행위등록\r\n동그라미 : 14. 물품확인\r\n동그라미 : 15. 범피스 → 가이드 → 물품구매모음 → 물품구매서식 및 필요서류안내, 승낙검수수의계약 기능을 활용하여 필요서류 정리\r\n동그라미 : 16. e호조 → 지출관리 → 지출품의 → 지출품의승인내역등록(21103)\r\n동그라미 : 17. 결재문서번호 검색 → 작성자나 제목으로 조회 → 선택\r\n동그라미 : 18. 사업상세 → 법정/보조/이자/재량은 예산내역 눌러서 확인 후 선택, 승인대상자는 보통 팀장님\r\n\r\n네모 : 품의유형 분기 일반/물품구입\r\n동그라미 : 품의유형에 따라 지출결의서 양식이 달라짐\r\n바 : 물품구입~관급자재 5가지는 계약요청을 할 수 있는 품의유형\r\n바 : 보통 간단한건 일반 사용함\r\n\r\n동그라미 : 19. 품의유형 → 일반\r\n동그라미 : 20. 품의액 → 금액입력 → 금액 입력 후 저장\r\n동그라미 : 21. 거래처 → 추가 → 거래처명 검색 → 거래처 더블클릭 → 공급금액/부가세액 입력 → 계좌검증\r\n동그라미 : 21.5 거래처 없으면 → 거래처 → 추가 → 신규 → 거래처상세에서 → 거래처명, 대표자명, 사업자등록번호, 주소입력 → 계좌번호목록 행추가후 → 금융기관, 계좌번호, 예금주명 입력 → 계좌검증 → 저장\r\n동그라미 : 22. 관리항목 → 계약대장등록여부 아니오 이미 되어있습니다\r\n동그라미 : 23. 일반상세 → 행추가 → 비고내용에 제목을 넣고 → 요청금액에 품의액 입력\r\n\r\n동그라미 : 19. 품의유형 → 물품구입\r\n동그라미 : 20. 품의액 → 금액입력 → 금액 입력 후 저장\r\n동그라미 : 21. 거래처 → 추가 → 거래처명 검색 → 거래처 더블클릭 → 공급금액/부가세액 입력 → 계좌검증\r\n동그라미 : 21.5 거래처 없으면 → 거래처 → 추가 → 신규 → 거래처상세에서 → 거래처명, 대표자명, 사업자등록번호, 주소입력 → 계좌번호목록 행추가후 → 금융기관, 계좌번호, 예금주명 입력 → 계좌검증 → 저장\r\n동그라미 : 22. 관리항목 → 계약대장등록여부 N → 납기일자는 물건 받은 날 → 납품예정일자는 보통은 견적일 + 2주 → 납품장소는 창고 또는 본인사무실\r\n동그라미 : 23. 물품상세 → 행추가 → 물품관리번호 검색 → 물품명 대충 맞는걸로... 없는것도 많음 귀찮음 → 물품명, 규격명, 단위명 개, 수량, 단가, 거래자 사업자등록번호 입력, 자체계약 체크\r\n\r\n동그라미 : 24. 첨부문서 → 파일추가 → 15번에서 정리한 서류 첨부\r\n동그라미 : 25. 공유범위 → 실국공개 해놓으면 후임자가 나중에 볼 때 편함\r\n동그라미 : 26. 원인행위등록요청 클릭\r\n\r\n\r\n네모 : 자금배정\r\n동그라미 : 27. e호조 → 자금관리 → 자금배정 → 수시배정요구등록 → 수시배정요구(54201)\r\n동그라미 : 28. 조회 → 사업명검색 → 본인예산 더블클릭\r\n동그라미 : 29. 신규 → 요구사유에 품의공문제목 쓰기 → 요구금액 입력 → 승인대상자 보통은 팀장님 → 저장 → 만들어진 내역 선택 후 승인요청\r\n\r\n네모 : 지출결의\r\n동그라미 : 보통 카드지출의 경우 경리주무관님이 맡아서 하십니다\r\n\r\n네모 : 지급\r\n동그라미 : 보통 경리 주무관님이 처리하심')))
    튜토리얼예산서어찌뽑버튼 = 버튼(지역프레임, 100, 50, '아이콘\\가이드탭\\튜토리얼\\튜토리얼예산서어찌뽑.PNG', (lambda : 기본.마크다운응용('제목 : 예산서 어찌 뽑?\r\n\r\n소제목 : 합본예산서\r\n네모 : e호조 → 예산관리 → 예산편성 → 예산서관리 → 합본예산서 (15100)\r\n네모 : 예산서구분은 세출 선택 → 출력\r\n네모 : 본예산 추경까지 같이 뽑힘')))
    튜토리얼승낙사항AtoZ버튼 = 버튼(지역프레임, 100, 100, '아이콘\\가이드탭\\튜토리얼\\튜토리얼승낙사항AtoZ.PNG', (lambda : 기본.마크다운응용('제목 : 승낙사항 A to Z\r\n네모 : 5천만원 이하의 계약의 경우 표준계약서를 작성하지 아니하고 업체로부터 관공서에서 요구하는 사항에 대해서 승낙하는 서류를 받고 간단히 처리하는 약식계약\r\n\r\n동그라미 : 200만원 이하 카드로 구매 시 승낙사항 생략 가능\r\n바 : 200만원 이하 카드로 제작/인쇄 시 승낙사항 써야함(구매가 아님)\r\n\r\n동그라미 : 납품예정일자는 넉넉하게 잡는게 좋음\r\n바 : 승낙사항의 납품예정일자 = 검수조서 납품기한 = e호조  납품예정일자\r\n\r\n동그라미 : 지연배상금 : 물품구매는 1000분의 0.8 입니다.\r\n바 : 공사 : 0.5, 용역 : 1.3, 운송 : 2.5\r\n\r\n동그라미 : 승낙일자 = 발주일자 = 원인행위일자\r\n\r\n\r\n\r\n네모 : 관련법률\r\n동그라미 : 지방자치단체를 당사자로 하는 계약에 관한 법률 시행령 제50조(계약서 작성의 생략 등) ①법 제14조제1항 단서에 따라 계약서의 작성을 생략할 수 있는 경우는 다음 각 호와 같다.\r\n바 : 계약금액이 5천만원 이하인 계약을 체결하는 경우\r\n\r\n동그라미 : 지방자치단체를 당사자로 하는 계약에 관한 법률 시행규칙 제48조(계약서의 작성을 생략하는 경우) 지방자치단체의 장 또는 계약담당자는 영 제50조에 따라 계약서의 작성을 생략하는 경우에는 계약상대자로부터 청구서, 각서, 협정서, 승낙사항 등 계약 성립의 증거가 될 수 있는 서류를 제출받아 갖춰 두어야 한다. 다만, 그 지방자치단체의 재무회계에 관한 규칙에서 따로 정하는 회계경리에 관한 서식에 따른 경우에는 그러하지 아니하다.\r\n\r\n동그라미 : 지방자치단체를 당사자로 하는 계약에 관한 법률 시행규칙 제75조(지연배상금률) 영 제90조제1항에 따른 지연배상금률은 다음 각 호와 같다.\r\n바 : 1. 공사: 1000분의 0.5\r\n바 : 2. 물품의 제조ㆍ구매(영 제16조제3항에 따라 소프트웨어사업 시 물품과 용역을 한꺼번에 입찰에 부치는 경우를 포함한다): 1000분의 0.8. 다만, 계약 이후 설계와 제조가 일괄하여 이루어지고, 그 설계에 대하여 발주한 지방자치단체의 장의 승인이 필요한 물품의 제조ㆍ구매의 경우에는 1000분의 0.5로 한다.\r\n바 : 3. 물품의 수리ㆍ가공ㆍ대여, 용역(영 제16조제3항에 따라 소프트웨어사업 시 물품과 용역을 한꺼번에 입찰에 부치는 경우 그 용역은 제외한다), 그 밖의 계약: 1000분의 1.3\r\n바 : 4. 운송ㆍ보관 및 양곡가공: 1000분의 2.5\r\n\r\n\r\n\r\n네모 : 200만원 이하 카드 사용시 승낙사항 생략\r\n동그라미 : 행정안전부 회계제도과-2137(20.5.7.)\r\n\r\n동그라미 : 현   황\r\n바 : 「지방자치단체 예산 및 기금의 회계관리에 관한 규칙」 (현)「지방자치단체 회계관리에 관한 훈령」개정에 따라 신용카드 또는 인터넷으로 200만원 이하 물품 구매 시 일반지출결의서를 사용하도록 하는 근거 삭제\r\n\r\n동그라미 : 적용안내\r\n바 : 「지방계약법 시행령」제50조에 따라 계약금액이 5천만원 이하인 계약을 체결하는 경우 계약서의 작성을 생략할 수 있으며, 같은 법 시행규칙 제48조에 따라 계약상대자로부터 계약성립의 증거가 될 수 있는 서류(청구서, 각서, 협정서, 승낙사항 등)를 제출받아 갖춰 두도록 하고 있음\r\n바 : 「지방자치단체 회계관리에 관한 훈령」별표5에는 신용카드를 사용할 수 있는 비목별 대상을 정하고 있으며, 「여신전문금융업법」에 의한 신용카드가맹점과 물품구매 또는 소규모 용역 제공 등에 대한 계약이행을 완료한 후 구매대금 지급방법으로 신용카드를 사용할 수 있음\r\n바 : 이와 관련하여, 신용카드 매출전표는 「여신전문금융업법」에 따른 신용공여의 증거로서 지방자치단체와 계약상대자 간의 계약성립의 증거로 볼 수 있을 것임\r\n바 : 따라서, 「지방자치단체 회계관리에 관한 훈령」별표5에 따라 수의계약 범위 내에서 소규모 물품 등을 구매하는 경우\r\n\r\n동그라미 : 신용카드 매출전표를 계약성립의 증거로 보아 계약서를 생략한 일반지출결의서 사용이 가능할 것으로 판단됨')))
    튜토리얼지출규칙기초편버튼 = 버튼(지역프레임, 100, 150, '아이콘\\가이드탭\\튜토리얼\\튜토리얼지출규칙기초편.PNG', (lambda : 기본.마크다운응용("제목 : 지출규칙 기초편\r\n소제목 : 나폴리탄 지출규칙\r\n네모 : 1. 청구서 날짜 3일 이내 지급하십시오.\r\n네모 : 2. 청렴서약서를 생략하는 규정은 존재하지 않습니다.\r\n네모 : 3. 200만원 미만이면 수의계약 체결 제한 확인서를 제출하지 않을 수 있습니다.\r\n네모 : 4. 물품검수조서 50만원 미만은 생략합니다.(우리 지자체)\r\n네모 : 5. 4번 규정은 존재하지 않습니다.\r\n네모 : 6. 서류 원본을 5년 안에 잃어버리면 징계받습니다.\r\n네모 : 7. 청구서, 납품서를 비전자 접수해야 한다는 규정은 없습니다.\r\n네모 : 8. 다만 계약의 이행확인이 필요한 서류(설계서, 착공계, 준공계 (제작)물품 납품계 등)의 경우 계약담당자가 사업부서와 공유하기 위해 감독관을 경유하도록 하는 등 계약사항 확인의 신뢰성 확보가 요구되므로 별도 절차(비전자문서 접수 등)가 있으면 좋긴 합니다.\r\n네모 : 9. 100만원 미만이면 완납증명서를 제출하지 않을 수 있습니다.(우리 지자체)\r\n네모 : 10. 9번 규정은 존재하지 않습니다. 일상경비만 입찰이 없어서 완납증명서를 생략합니다.\r\n네모 : 11. 건강보험, 국민연금 완납증명서는 제출해야하지만, 고용과 산재는 완납 사실 증명을 갈음할 수 있습니다.\r\n네모 : 12. 국세완납증명서와 지방세완납증명서는 수의계약에서 생략이 가능합니다.\r\n네모 : 13. 사업자등록증과 통장사본에는 원본대조필 도장이 찍혀 있어야 합니다.\r\n\r\n\r\n\r\n\r\n소제목 : 관련법령\r\n네모 : 1. 청구서 날짜 3일 이내 지급하십시오.\r\n동그라미 : 보통은 5일 이지만, 코로나 경제위기 같은 경우는 3일 취급, 공휴일 토요일 제외함, 감사가 심심하면 이걸로 공격함, 이거 때문에 품의공문 처음부터 다시 쓰고 서류 다시 받는 경우도 빈번함, 청구서 날짜 비워서 받는 이유도 이거 때문임\r\n바 : 지방자치단체를 당사자로 하는 계약에 관한 법률 시행령 67조 : ① 법 제18조제2항에 따라 지방자치단체의 재정부담이 되는 계약의 대가는 제64조에 따른 검사를 완료한 후 계약상대자의 청구를 받은 날부터 5일(「재난 및 안전관리 기본법」 제3조제1호에 따른 재난이나 경기침체, 대량실업 등으로 인한 국가 또는 해당 지역의 경제위기를 극복하기 위해 행정안전부장관이 기간을 정하여 고시한 경우에는 계약상대자의 청구를 받은 날부터 3일을 말하며, 공휴일과 토요일은 제외한다. 이하 이 조에서 같다) 이내에 지급하여야 한다.\r\n\r\n네모 : 2. 청렴서약서를 생략하는 규정은 존재하지 않습니다.\r\n동그라미 : 원래는 금액이 얼마든 매번 첨부해야하나... 1년 마다 일괄수령해버리는 경우도 있습니다.\r\n바 : 지방자치단체를 당사자로 하는 계약에 관한 법률 제6조의2(청렴서약제) ① 지방자치단체의 장 또는 계약담당자는 계약의 투명성과 공정성을 높이기 위하여 입찰참가자 또는 수의계약의 계약상대자에게 청렴서약서를 제출하도록 하여야 한다.\r\n\r\n네모 : 3. 200만원 미만이면 수의계약 체결 제한 확인서를 제출하지 않을 수 있습니다.\r\n동그라미 : 「국가를 당사자로 하는 계약에 관한 법률 시행령」제30조제7항 및 동법 시행규칙 제33조제3항, 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행규칙」 제33조에 따라 ‘수의계약 체결 시 견적서 제출을 생략할 수 있는 경우'에 대해서는 수의계약 체결 제한 확인서를 제출받지 않을 수 있음\r\n동그라미 : 【수의계약 체결 시 견적서 제출생략 대상】\r\n바 : 1. 전기, 가스, 수도 등의 공급계약을 체결하는 경우\r\n바 : 2. 추정가격이 200만원 미만인 물품의 제조·구매·임차 및 용역계약을 체결하는 경우\r\n바 : 3. 추정가격이 200만원 미만인 물품을 「여신전문금융업법」에 따른 신용카드로 구매하는 경우\r\n바 : 4. 국가 및 다른 지방자치단체와 수의계약을 체결하는 경우\r\n\r\n네모 : 4. 물품검수조서 50만원 미만은 생략한다는 규정은 존재하지 않습니다.\r\n동그라미 : 공유재산 및 물품 관리법 제68조(취득) ① 물품관리관은 제57조에 따른 수급관리계획에 포함된 물품의 경우 계약담당공무원에게 그 계획의 범위에서 물품의 취득에 필요한 조치를 할 것을 청구하여야 하며, 그 밖의 물품의 경우 필요하다고 인정할 때마다 취득에 필요한 조치를 할 것을 청구하여야 한다.\r\n바 : ③ 물품은 지방자치단체의 장 또는 그 위임을 받은 공무원이 지명하는 관계 공무원이나 기술자의 검사와 검수를 받지 아니하고는 취득할 수 없다.\r\n동그라미 : 지방자치단체를 당사자로 하는 계약에 관한 법률 시행령 제65조(검사조서의 작성 생략) 법 제17조제3항 단서에서 “대통령령으로 정하는 금액”이란 계약금액 3천만원을 말한다.\r\n\r\n네모 : 5. 4번 규정은 존재하지 않습니다.\r\n동그라미 : 우리 지자체 자치조례 시행규칙 몇번이고 읽어 보았으나... 50만원이라는 내용은 없었습니다.\r\n\r\n네모 : 6. 서류 원본을 5년 안에 잃어버리면 징계받습니다.\r\n동그라미 : 지방자치단체 회계관리에 관한 훈령 제112조(증거서류 및 장부의 보존) ① 법 제46조의 회계관계공무원은 그 소관에 속하는 증거서류 및 장부를 「공공기록물 관리에 관한 법률 시행령」 제26조제1항에 따라 5년간 보존하여야 한다.\r\n\r\n네모 : 10. 9번 규정은 존재하지 않습니다. 일상경비만 입찰이 없어서 완납증명서를 생략합니다.\r\n동그라미 : 국민건강보험법 제81조의4(보험료의 납부증명) ① 제77조에 따른 보험료의 납부의무자(이하 이 조에서 “납부의무자”라 한다)는 국가, 지방자치단체 또는 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관(이하 이 조에서 “공공기관”이라 한다)으로부터 공사ㆍ제조ㆍ구매ㆍ용역 등 대통령령으로 정하는 계약의 대가를 지급받는 경우에는 보험료와 그에 따른 연체금 및 체납처분비의 납부사실을 증명하여야 한다. 다만, 납부의무자가 계약대금의 전부 또는 일부를 체납한 보험료로 납부하려는 경우 등 대통령령으로 정하는 경우에는 그러하지 아니하다.\r\n\r\n동그라미 : 국민연금법 제95조의2(연금보험료등의 납부증명) ① 제88조에 따른 연금보험료의 납부 의무자(이하 이 조에서 “납부 의무자”라 한다)가 국가, 지방자치단체 또는 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관으로부터 공사ㆍ제조ㆍ구매ㆍ용역 등 대통령령으로 정하는 계약의 대가를 지급받는 경우에는 연금보험료와 그에 따른 연체금 및 체납처분비(이하 이 조에서 “연금보험료등”이라 한다)의 납부사실을 증명하여야 한다. 다만, 납부 의무자가 계약대금의 전부 또는 일부를 체납한 연금보험료로 납부하려는 경우 등 대통령령으로 정하는 경우에는 그러하지 아니하다.\r\n\r\n동그라미 : 국민연금법 시행령 제70조의4(납부사실 증명의 예외) 법 제95조의2제1항 단서에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 납부사실을 증명하지 아니하여도 된다.\r\n바 : 4. 납부 의무자가 받을 대금이 다음 각 목의 어느 하나에 해당하는 경비나 자금으로 지급되는 경우\r\n바 : 가. 「국고금 관리법 시행령」 제31조에 따른 관서운영경비\r\n바 : 나. 「지방회계법 시행령」 제38조제1항에 따른 일상경비등\r\n바 : 다. 그 밖의 일상경비적 성격의 자금으로서 보건복지부장관이 정하여 고시하는 자금\r\n\r\n네모 : 11. 건강보험, 국민연금 완납증명서는 제출해야하지만, 고용과 산재는 완납 사실 증명을 갈음할 수 있습니다.\r\n동그라미 : 고용보험 및 산업재해보상보험의 보험료징수 등에 관한 법률 제29조의4(보험료등의 완납증명)\r\n바 : ① 보험료등의 납부의무자가 국가, 지방자치단체 또는 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관 등 대통령령으로 정하는 기관으로부터 공사ㆍ제조ㆍ구매ㆍ용역 등 대통령령으로 정하는 계약의 대가를 지급받으려면 보험료등의 완납(完納) 사실을 증명하여야 한다. 다만, 납부의무자가 계약대금의 전부 또는 일부로 보험료등을 납부하려는 경우 등 대통령령으로 정하는 경우에는 그러하지 아니하다.\r\n바 : ② 납부의무자가 제1항에 따라 보험료등의 완납 사실을 증명하여야 하는 경우 같은 항의 계약을 담당하는 주무관서 또는 공공기관 등은 납부의무자의 동의를 받아 공단 또는 건강보험공단에 조회하여 보험료등의 납부 여부를 확인하는 것으로 제1항에 따른 완납 사실 증명을 갈음할 수 있다.\r\n\r\n네모 : 12. 국세완납증명서와 지방세완납증명서는 수의계약에서 생략이 가능합니다.\r\n동그라미 : 국세징수법 시행령 제91조(납세증명서 제출의 예외) 납세자는 법 제107조제1항제1호에 따라 국가, 지방자치단체 등으로부터 대금을 지급받을 경우라도 다음 각 호의 어느 하나에 해당하는 경우에는 납세증명서를 제출하지 않을 수 있다.\r\n바 : 1. 「국가를 당사자로 하는 계약에 관한 법률 시행령」 제26조제1항 각 호(같은 항 제1호라목은 제외한다) 및 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제25조제1항 각 호(같은 항 제7호가목은 제외한다)에 해당하는 수의계약에 따라 대금을 지급받는 경우\r\n\r\n동그라미 : 지방세징수령 시행령 제5조(납세증명서 제출의 예외) ① 법 제5조제1항제1호의 경우에 다음 각 호의 어느 하나에 해당하면 납세증명서를 제출하지 아니하여도 된다.\r\n\r\n바 : 1. 「국가를 당사자로 하는 계약에 관한 법률 시행령」 제26조제1항 각 호의 규정(같은 항 제1호라목은 제외한다) 및 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제25조제1항 각 호의 규정(같은 항 제7호가목은 제외한다)에 해당하는 수의계약과 관련하여 대금을 지급받는 경우\r\n\r\n네모 : 13. 사업자등록증과 통장사본에는 원본대조필 도장이 찍혀 있어야 합니다.\r\n동그라미 : 지출할 때 상대방이 정당한 채권자가 맞는지 확인하기 위함입니다.\r\n동그라미 : 지방자치단체 회계관리에 관한 훈령 제33조(지출 및 지급의 원칙) \r\n바 : ③ 지출원 및 출납원, 통합지출관은 각종 지급명령 및 대가 등을 지급할 때에는 정당한 채권자에게 계좌로 입금하는 것을 원칙으로 한다. 다만, 시행령 제52조에 해당하는 경우에는 그러하지 아니할 수 있다.  ")))
    튜토리얼확정내시송신하기버튼 = 버튼(지역프레임, 100, 200, '아이콘\\가이드탭\\튜토리얼\\튜토리얼확정내시송신하기.PNG', (lambda : 기본.마크다운응용('제목 : 확정내시 송신하기\r\n소제목:국도비 보조금 확정통보 공문확인\r\n네모:확정내시 공문을 확인\r\n네모:e호조, 보탭e에 반영이 안된경우 담당자에게 확인\r\n\r\n소제목:e호조 사업담당자 변경(111011)\r\n네모:e호조 → 재정계획 → 사업정보 → 정보관리사업 → 정보관리사업목록\r\n네모:조회 후 사업명 검색 → 사업명 더블클릭\r\n네모:담당자 → 정에는 변경된 담당자 이름 → 부에는 경리 담당자 이름 → 저장\r\n\r\n소제목:보탬e 확정내시관리(91017)\r\n네모:e호조 → 보탬e → 보조금예산 → 보조금통보(내시)관리 → 확정통보(확정내시)관리\r\n네모:사업명 입력 후 조회 → 해당사업 선택 후 신규 클릭 → 지자체보조사업명 입력 후 조회 → 선택 → 국비 도비 시군구비 입력 → 저장 → 담당자연락처 입력 → 사이트URL입력\r\n\r\n소제목:보탬e 기초교부신청(92011)\r\n네모:e호조 → 보탬e → 교부관리 → 기초교부관리 → 기초교부신청\r\n네모:국고내역 사업명 검색 후 조회 → 사업선택체크 → 세입계좌번호 선택(모르면 경리주무관님 문의) → 송신 → 저장 → 확인 ※ 예산서와 공문 금액이 다르면 예산팀에서 송신해야함\r\n\r\n소제목:확정내시\r\n네모:확정내시 : 굳을 확 + 정할 정 + 오다 내 + 보일시 : 한자로는 확정된 사항을 문서로 알린다는 뜻이며, 행정용어로는 중앙정부가 지방자치단체에 배분할 예산의 최종 확정 금액을 통보하는 것을 의미합니다.')))
    튜토리얼성과목표지표관리버튼 = 버튼(지역프레임, 100, 250, '아이콘\\가이드탭\\튜토리얼\\튜토리얼성과목표지표관리.PNG', (lambda : 기본.마크다운응용('제목 : 성과목표 지표관리\r\n소제목:성과목표 및 지표관리(62009)\r\n네모:e호조 → 결산관리 → 성과보고 → 성과보고자료관리 → 성과목표 및 지표관리\r\n네모:성과분석 내용은 1년전꺼 복사해서 재활용\r\n네모:하단 성과지표의 실적치 및 달성률 입력\r\n\r\n소제목:단위사업 성과관리(62010)\r\n네모:e호조 → 결산관리 → 성과보고 → 성과보고자료관리 → 단위사업 성과관리\r\n네모:주요추진성과는 위에꺼 사업별로 분해해서 입력')))
    튜토리얼보조금반납명세서버튼 = 버튼(지역프레임, 100, 300, '아이콘\\가이드탭\\튜토리얼\\튜토리얼보조금반납명세서.PNG', (lambda : 기본.마크다운응용('제목 : 보조금 반납 명세서관리\r\n네모: 보통 2월쯤에 작년에 보조금 어떻게 반납했는지 보탬e에 입력해야하는 귀찮은 업무가 있읍니다.\r\n\r\n소제목:보조금 반납 명세서관리(보탬e 94024)\r\n네모:e호조 → 보탬e → 보조금결산관리 → 보조금결산 → 보조금반납명세서관리\r\n네모: 회계연도 작년 날짜로 선택\r\n네모: 보조사업구분에서 국고인지 시도비인지 정해서 조회하고\r\n네모: 반납액 반납이자 반납일 등 적고 저장하면 됩니다.\r\n원: 오름차순 내림차순 정렬 가능하니 꼭 활용합시다!\r\n\r\n소제목:사업명이 없어요!\r\n네모: 작년 사업이 아니라 2년 이전 사업인 경우에는 등록을 누르고, 조회 옆에 초기화버튼을 눌러서 검색 후 저장한 뒤에 입력하시면 됩니다!')))
    튜토리얼예산입금확인버튼 = 버튼(지역프레임, 100, 350, '아이콘\\가이드탭\\튜토리얼\\튜토리얼예산입금확인.PNG', (lambda : 기본.마크다운응용('제목 : 예산 입금확인\r\n소제목 : 송금통지수신내역조회(211116)\r\n네모:e호조 → 지출관리 → 지출품의 → 지출품의 → 송금통지수신내역조회\r\n네모:교부일자 기간 넉넉하게 지정 → 적요에 사업이름 넣고 → 조회\r\n원:송금 확인하고 예산 사용하시면 됩니다!')))
    튜토리얼국비반납금납부매핑버튼 = 버튼(지역프레임, 100, 400, '아이콘\\가이드탭\\튜토리얼\\튜토리얼국비반납금납부매핑.PNG', (lambda : 기본.마크다운응용('제목 : 보조금반환지출내역 매핑(잔액 및 이자 반납)\r\n소제목:국비 반납금 및 이자 납부\r\n네모 : 일반지출처럼 처리 후 → 임시저장\r\n네모 : 보탬E → 현황모니터링 → 보조금반환지출매핑관리 → 보조금반환지출매핑관리(96050)\r\n네모 : 날짜 넉넉하게 주고 조회\r\n네모 : 보조금반환지출내역에서 미매핑된 사업에 앞에 네모 선택 → 신규 → 국고내역사업명 넣고 조회 및 선택 → 잔액 및 이자 입력 후 저장하면 매핑 끝\r\n\r\n소제목:도비 반납금 및 이자 납부\r\n네모 : 일반지출과 동일함')))
    튜토리얼연가어찌씀버튼 = 버튼(지역프레임, 300, 50, '아이콘\\가이드탭\\튜토리얼\\튜토리얼연가어찌씀.PNG', (lambda : 기본.마크다운응용('제목 : 연가 어찌 씀?\r\n\r\n소제목 : 연가쓰는 방법\r\n네모 : 인사랑 → 복무관리 → 연가관리 → 연가신청\r\n네모 : 신규 → 날짜 지정 → 저장 → 기안상신\r\n네모 : 서무 협조 → 팀장 검토 → 과장 전결 → 확인\r\n\r\n소제목 : 연가 몇 개임?\r\n네모 : 재직기간 1개월 이상 1년 미만 : 11개\r\n네모 : 재직기간 1년 이상 3년 미만 : 15개\r\n네모 : 재직기간 3년 이상 4년 미만 : 16개\r\n네모 : 재직지간 4년 이상 5년 미만 : 17개\r\n네모 : 재직기간 5년 이상 6년 미만 : 20개\r\n네모 : 재직기간 6년 이상 : 21개\r\n\r\n네모 : 재직기간 : 임명된 날부터 연가사용 직전일 까지\r\n동그라미 : 휴직기간, 정직기간, 직위해제기간 및 강등 처분에 따라 직무에 종사하지 못하는 기간은 산입 안 함\r\n\r\n동그라미 : 다음의 휴직기간은 산입 함\r\n바 : 자녀 1인당 3년의 육아휴직\r\n바 : 법령에 따른 의무 수행으로 인한 휴직\r\n바 : 「공무원 재해보상법」에 따른 공무상 질병 또는 부상으로 인한 휴직\r\n\r\n동그라미 : 다음은 재직기간에 산입 할 수 있다\r\n바 : 군인 근무경력\r\n바 : 시간선택제공무원 근무경력\r\n바 : 공중보건의 근무경력\r\n\r\n동그라미 : 연도 중 결근ㆍ휴직(법 제71조제1항제1호에 따른 휴직 중 공무상 질병 또는 부상으로 인한 휴직은 제외한다)ㆍ정직ㆍ강등ㆍ직위해제된 사실 및 인사혁신처장이 정하는 사실상 직무에 종사하지 않은 기간이 없는 공무원으로서 다음 각 호의 어느 하나에 해당하는 공무원에 대해서는 다음 해에만 제1항의 재직기간별 연가 일수에 각각 1일을 더한다.\r\n바 : 1. 병가(제18조제2항에 따른 병가는 제외한다)를 받지 않은 공무원\r\n바 : 2. 제16조제5항에 따른 연가보상비를 받지 못한 연가 일수가 남아 있는 공무원\r\n\r\n소제목 : 기타\r\n네모 : 연가 : 해 년(연) + 한가할, 틈 가\r\n네모 : 직장에서 직원들에게 1년에 일정한 기간을 쉬도록 해 주는 유급 휴가')))
    튜토리얼인사랑당직보고버튼 = 버튼(지역프레임, 300, 100, '아이콘\\가이드탭\\튜토리얼\\튜토리얼인사랑당직보고.PNG', (lambda : 기본.마크다운응용('제목 : 당직\r\n\r\n소제목 : 당직보고\r\n네모 : 인사랑 → MY인사랑 → 복무관리 → 당직관리 → 당직보고\r\n네모 : 추가 → 전화번호 그냥 사무실번호 입력 → 당직구분 일직/숙직 선택 → 당직근무자 → 조회 → 조회 → 본인선택 → 보통은 외 0명 → 보고내용에 당직보고 입력 →  보고내역생성\r\n\r\n소제목 : 당직근무일지\r\n네모 : 당직근무일지\r\n동그라미 : 인사랑 → MY인사랑 → 복무관리 → 당직관리 → 당직근무일지 → 추가\r\n동그라미 : 당직구분 및 날씨 선택\r\n동그라미 : 당직자정보에서 확인 네모 체크\r\n바 : 지시받은사항 : 당직근무철저\r\n바 : 행정사항 : 각실보안점검\r\n바 : 지시한사항 : 없음\r\n바 : 조치결과 : 이상없음\r\n바 : 시도보고사항 : 없음\r\n바 : 인수인계사항 : 없음\r\n동그라미 : 저장 → 확인\r\n\r\n네모 : 순찰점검사항(일직)\r\n동그라미 : 순찰점검사항 → 행추가\r\n바 : 순찰 08:30, 09:00, 특이사항없음\r\n바 : 순찰 17:30, 18:00, 특이사항없음\r\n바 : 순찰 18:00, 24:00, 재택근무\r\n바 : 순찰 00:00, 08:00, 재택근무\r\n바 : 순찰 08:00, 08:30, 특이사항없음\r\n동그라미 : 연락사항 → 행추가\r\n바 : 연락사항 : 해당없음\r\n바 : 성명 : 해당없음\r\n바 : 이상유무 : 무\r\n동그라미 : 저장 → 확인 → 당직근무일지\r\n\r\n네모 : 기안전송\r\n동그라미 : 당직보고내역 체크 → 일직 체크 → 기안전송\r\n동그라미 : 행추가 → 서무(검토) → 주무팀장(전결)\r\n동그라미 : 결재신청 → 확인 → 확인')))
    튜토리얼당직근무대체휴무버튼 = 버튼(지역프레임, 300, 150, '아이콘\\가이드탭\\튜토리얼\\튜토리얼당직근무대체휴무.PNG', (lambda : 기본.마크다운응용('제목 : 당직근무 대체휴무\r\n\r\n소제목 : 당직근무 대체휴무 사용하는 방법\r\n네모 : 인사랑 → 복무관리 → 연가외휴가관리 → 대체휴무\r\n네모 : 신규 → 대체휴무사유 : 1월 1일 일직 → 당직휴무 체크 → 날짜지정 → 저장\r\n네모 : 기안상신 → 서무 협조 → 팀장 검토 → 과장 전결 → 확인\r\n\r\n소제목 : 취소하는 방법\r\n네모 : 결재가 진행중인 경우\r\n동그라미 : 인사랑 → 복무관리 → 결재함 → 기안상신함 → 날짜지정 후 조회 → 취소할 항목(결재진행) 더블클릭 → 상신취소 → 확인 → 확인 → 취소할 항목(반송) 더블클릭 → 삭제 → 확인 → 확인\r\n동그라미 : 인사랑 → 복무관리 → 연가외휴가관리 → 대체휴무 → 날짜지정 후 조회 → 취소할 항목 더블클릭 → 삭제 → 확인 → 확인\r\n\r\n소제목 : 대체휴무 관련법령\r\n네모 : 국가공무원 복무규칙 제14조(숙직근무자의 교대 취침 등)\r\n동그라미 : ① 각급 기관의 장은 숙직근무자가 2명 이상일 때에는 일정한 시간을 정하여 교대로 취침하게 할 수 있고, 1명일 때에는 기관의 기능 및 성격 등을 고려하여 소속 중앙행정기관의 장의 승인을 받아 제23조에 따른 당직임무를 수행한 후 일정한 시간을 정하여 취침하게 할 수 있다.\r\n동그라미 : ② 각급 기관의 장은 업무상 불가피한 경우를 제외하고는 당직근무자(재택당직근무자는 제외한다)에 대하여 그 근무종료시각이 속하는 날(근무종료시각이 속하는 날이 토요일 또는 공휴일인 경우에는 그 다음 정상근무일부터 토요일 또는 공휴일을 제외한 10일째 되는 날까지의 기간 중 1일을 말한다)의 일정 시간 동안 휴무하게 해야 한다.')))
    튜토리얼기본결재선지정하기버튼 = 버튼(지역프레임, 300, 200, '아이콘\\가이드탭\\튜토리얼\\튜토리얼기본결재선지정하기.PNG', (lambda : 기본.마크다운응용('제목 : 기본결재선 지정하기\r\n소제목 : 출장 결재선 지정\r\n네모 : 인사랑 → 복무관리 → 결재함 → 결재선관리\r\n네모 : 신규 → 업무구분 출장관리 → 업무별 순번 1번 → 기준결재선Y → 결재선 제목은 기본출장\r\n네모 : 행추가 → 성명검색 팀장님 검토 결재순서 1\r\n네모 : 행추가 → 성명검색 과장님 전결 결재순서 2\r\n네모 : 저장\r\n\r\n소제목 : 휴가(연가, 병가등) 결재선 지정\r\n네모 : 인사랑 → 복무관리 → 결재함 → 결재선관리\r\n네모 : 신규 → 업무구분 휴가관리 → 업무별 순번 1번 → 기준결재선Y → 결재선 제목은 기본휴가\r\n네모 : 행추가 → 성명검색 서무님 협조 결재순서 1\r\n네모 : 행추가 → 성명검색 팀장님 검토 결재순서 2\r\n네모 : 행추가 → 성명검색 과장님 전결 결재순서 3\r\n네모 : 저장')))
    튜토리얼자기개발계획수립버튼 = 버튼(지역프레임, 300, 250, '아이콘\\가이드탭\\튜토리얼\\튜토리얼자기개발계획수립.PNG', (lambda : 기본.마크다운응용('제목 : 자기개발계획수립\r\n네모 : 차세대인사랑 → 교육훈련 → 교육훈련 → 자기개발계획서수립\r\n네모 : 왼쪽 자기개발계획서 목록 행추가 → 년도선택 → 저장 → 선택\r\n네모 : 오른쪽 자기개발계획서 상세내용 행추가\r\n원: 교육학습계획, 시기, 교육시간, 비고\r\n원: AI활용방법, 1월1일~1월31일, 50시간, 개인학습\r\n네모: 총합 80시간 이상 작성 후 저장 후 신청 후 저장\r\n네모:다시 조회 해보고 신청상태 신청 뜨면 된거임')))
    튜토리얼정보공개정보부존재버튼 = 버튼(지역프레임, 400, 50, '아이콘\\가이드탭\\튜토리얼\\튜토리얼정보공개정보부존재.PNG', (lambda : 기본.마크다운응용('제목 : 정보부존재\r\n네모:참고 : 2025년 서울특별시 정보공개 업무 매뉴얼 : 52p\r\n\r\n소제목 : 정보공개법 제11조\r\n네모:⑤ 공공기관은 정보 공개 청구가 다음 각 호의 어느 하나에 해당하는 경우로서 「민원 처리에 관한 법률」에 따른 민원으로 처리할 수 있는 경우에는 민원으로 처리할 수 있다.\r\n원:1. 공개 청구된 정보가 공공기관이 보유･관리하지 아니하는 정보인 경우\r\n원:2. 공개 청구의 내용이 진정･질의 등으로 이 법에 따른 정보공개 청구로 보기 어려운 경우\r\n\r\n소제목:정부 부존재의 유형\r\n네모:공공기관이 청구된 정보를 생산･접수하지 않은 경우\r\n\r\n네모:정보를 취합･가공해야 하는 경우\r\n원:공공기관이 정보를 취합･가공하여 제공할 의무는 없으나, 업무 상황, 정보 관리방식･제공 형태등을 고려하여 신중하게 취합･가공 여부 판단\r\n원:별도 취합･가공이 필요한 청구의 경우 원 정보 그대로 공개 가능\r\n바:원본 공개가 오히려 큰 업무 부담을 유발하고 청구인도 가공에 동의하면 제한적 가공 가능\r\n원:비공개 및 공개 부분이 쉽게 분리되어 부분 공개가 가능하면 가급적 공개\r\n\r\n네모:공공기록물법 등의 보존기간 경과로 폐기된 경우\r\n원:귀하께서 청구하신 2002년 ○○사업 관련 검토보고서는 ○○법 시행령 제○조에 따라 보존 연한이 5년으로, 2007년에 폐기하여 정보부존재 통지함을 알려 드립니다.\r\n\r\n네모:정보를 특정하지 않고 포괄적으로 청구한 경우\r\n\r\n원:공개를 청구하는 정보의 내용은 사회 일반인 관점에서 청구 대상 정보의 내용과 범위를 확정할 수 있을 정도로 특정되어 있어야 함(대법원 2000두9212)\r\n바:청구를 받은 공공기관의 전문직원이 합리적인 노력으로 그 정보가 기록되어 있는 문서 등을 특정할 수 있는 정도로 청구인이 얻고자 하는 정보의 내용을 제출(서울행법 2006구합20716)\r\n\r\n원:청구 기간과 내용 등 청구 정보가 특정되지 않은 경우(부존재 처리)\r\n바:협회와 관련된 주요 감사 내용의 문건: 기간과 감사에 관한 내용이 특정되지 않음\r\n\r\n원:청구 정보가 다수 규정과 업무･조직･프로그램 등에 걸쳐있는 경우(부존재 처리)\r\n바:전년도 문화사업 계획 관련 공문･예산 문서 일체: 특정 부서나 사업에 한정되지 않음\r\n\r\n원:정보가 특정되지 않아 공개량이 지나치게 과다한 경우(부존재 처리)\r\n바:교정 기간 내 수용자 처우에 대한 법무부 장관 지시 사항\r\n\r\n원:정보가 구체적으로 특정된 것처럼 보이나 실제 내용이 구체적으로 특정되지 않아 지나치게 과다한 경우(부존재 처리)\r\n바: 기관장 업무추진비와 전 부서와 관련된 42개 항목의 정보공개 청구와 청구일 다음날에 2개 부서와 관련 15개 항목의 정보공개를 청구하는 등 양이 방대하여 모든 정보를 공개하기 위해서는 막대한 인력과 시간이 소요(강원도행정심판위원회 2018-13)\r\n\r\n네모:포괄적 청구에 해당할 경우 민원 처리에 관한 법률 제22조에 따라 보완 요청하고 그 여부에 따라 처리\r\n원:보완 요청에도 불구하고 적절히 보완되지 않은 경우, 정보부존재 검토\r\n원:보완 요구는 접수 후 즉시 문서･말･전화 등의 방법으로도 가능하나, 민원인이 서면으로할 것을 요구한 경우에는 문서로 하여야 함(민원 처리에 관한 법률 제22조, 영 제24조)')))


def 가이드학교감염병단계가이드창():
    지역프레임 = 우측새탭(창, 50, 0, 600, 500)
    학교감염병발생시대응단계버튼 = 버튼(지역프레임, 0, 50, '아이콘\\가이드탭\\학교감염병\\학교감염병발생시대응단계.PNG', (lambda : 기본.마크다운응용('제목:감염병 대응 단계\r\n소제목:한줄 요약\r\n네모:1단계 : 감염병 의심되는 증상을 보이는 학생을 발견\r\n네모:2단계 : 감염병 의료기관 진단(의심) 1명 발생\r\n네모:3단계 : 감염병 의료기관 진단(의심) 2명 이상 발생(유행 의심 기준 충족)\r\n\r\n\r\n소제목:1단계\r\n네모:감염병 유증상자 발견 → 의료기관 진료 → 감염병 진단(의심) 확인 → 2단계\r\n네모 : 보건소에 전화로 알림(정보공유)\r\n\r\n네모:학생(유증상자)\r\n원:학생의 주 증상이 기침, 발열, 인후통, 침샘비대 등인 경우 마스크 착용\r\n원:의료기관 진료를 볼 수 있도록 함\r\n원:학교보건법 제8조(등교 중지)에 따라 법정감염병 진단검사 결과를 기다리는 중에는 등교 중지시킬 수 있음(의심환자)\r\n바:학교의 장은 제7조에 따른 건강검사의 결과나 의사의 진단 결과 감염병에 감염되었거나 감염된 것으로 의심되거나 감염될 우려가 있는 학생 및 교직원에 대하여 대통령령으로 정하는 바에 따라 등교를 중지시킬 수 있다.\r\n\r\n네모:추가 업무\r\n원:교실 환기 및 소독\r\n원:학생 위생수칙 교육\r\n\r\n\r\n소제목:2단계\r\n네모:감염병 환자 발생 → 보건소신고(신고가 필요한 법정감염병)\r\n네모:감염병 환자 추가발생 파악 → 유행의심기준 충족 → 3단계\r\n네모:학교 감염병오피스 2단계 사전 사례조사 실시(집단설사 역학자료, 호흡기 역학자료)\r\n\r\n네모:감염병 환자\r\n원:감염병 환자 발생사실을 학교장에게 보고\r\n원:나이스(NEIS)로 교육(지원)청에 보고\r\n원:신고가 필요한 법정감염병인 경우 보건소에 신고\r\n\r\n네모: 신고가 필요한 법정감염병\r\n원:콜레라, 장티푸스, 파라티푸스, 세균성이질, 장출혈성 대장균 감염증, A형간염, 홍역, 결핵\r\n원:법적 근거 : ｢감염병의 예방 및 관리에 관한 법률｣ 제12조 및 시행규칙 제8조\r\n\r\n네모:추가 업무\r\n원:능동감시 실시\r\n원:밀접접촉자 파악 및 관리\r\n원:예방교육 실시\r\n\r\n네모:능동감시 체계(2단계)\r\n원:감염병 환자가 발생한 학급이 있는 동일한 층의 학급\r\n원:이동식 수업 시 감염병 환자와 함께 수업을 들은 학생들 전원\r\n원:수인성 및 식품매개 감염병의 경우 환자와 같은 음식을 먹은 학생 전체\r\n\r\n네모:유행의심여부 판단\r\n원: 학교 자체적으로 감염병 유행 여부를 판단하는 것보다 보건소의 역학조사 결과에 따르는 것이 바람직함\r\n원:다만, 학교에서는 감염병 확산의 선제적 대응을 위해 ‘유행의심 기준’에 따라 판단하고 이에 해당하면 실제 유행 여부가 불확실하더라도 대응 제3단계의 활동 수행\r\n\r\n네모:유행의심기준\r\n원:최대 잠복기 이내에 동일 학급에서 의심 또는 확진 환자 2명 이상 발생한 경우\r\n원:최초 환자와 동일 학급은 아니지만 추가 환자가 이동식 수업이나 급식 등 공통된 공간에 노출되어 관련성이 의심되는 경우\r\n바:사례 1 : 최초 환자와 같은 학급은 아니지만 추가 환자가 최초 환자가 발견된 당일 이동식 수업을함께 들었음이 확인되면 유행의심 기준을 충족함\r\n바:사례 2 : 서로 다른 학급 학생인 2명의 (의심)환자가 증상 발생 하루 전 학교 구내 매점에서 김밥을 먹은 것으로 확인 되면 유행의심 기준을 충족함\r\n\r\n\r\n소제목:3단계\r\n네모:유행의심 상황과 환자발생 현황을 학교장과 교육(지원)청에 보고\r\n네모:유행의심 상황을 나이스(NEIS)에 보고\r\n네모:능동감시 체계 강화\r\n네모:유행확산 정도에 따라 학사일정 조정 및 각종 교육활동에 대한 제한 검토 실시\r\n네모:등교중지 학생의 출석 인정처리 및 수업결손 대책 마련\r\n네모:유증상자 학원 등원 및 단체활동 자제요청 가정통신문 발송\r\n\r\n\r\n네모:능동감시 체계(3단계)\r\n원:전체 학급으로 확대\r\n원:학생/보호자에 대한 설문, 신체검사(발열 측정 등) 중 적절한 방법으로 매일 1회 이상 파악\r\n바:전체 학생 대상의 발열 검사는 권장하지 않으며 발열 여부에 대한 감시가 필요한 경우, 각 학급별로 본인이 열이 있다고 한 학생들에 대한 선별적인 검사 권고')))
    학교감염병예방단계버튼 = 버튼(지역프레임, 0, 100, '아이콘\\가이드탭\\학교감염병\\학교감염병예방단계.PNG', (lambda : 기본.마크다운응용('제목:감염병 예방단계\r\n네모:평상시의 평화로운 상황\r\n네모:수동감시체계 운영')))
    학교감염병1단계버튼 = 버튼(지역프레임, 100, 100, '아이콘\\가이드탭\\학교감염병\\학교감염병1단계.PNG', (lambda : 기본.마크다운응용('제목:학교감염병 1단계\r\n네모:감염병 증상이 있는 환자를 발견한 상황입니다\r\n네모:유증상자 발견 → 의료기관 진료 → 감염병 진단(의심) 확인 → 학교감염병 2단계\r\n\r\n네모:학생(유증상자) 관리\r\n원:학생의 주 증상이 기침, 발열, 인후통, 침샘비대 등인 경우 마스크 착용\r\n원:의료기관 진료를 볼 수 있도록 함\r\n원:학교보건법 제8조(등교 중지)에 따라 법정감염병 진단검사 결과를 기다리는 중에는 등교 중지시킬 수 있음(의심환자)\r\n바:학교의 장은 제7조에 따른 건강검사의 결과나 의사의 진단 결과 감염병에 감염되었거나 감염된 것으로 의심되거나 감염될 우려가 있는 학생 및 교직원에 대하여 대통령령으로 정하는 바에 따라 등교를 중지시킬 수 있다.\r\n\r\n네모:추가업무\r\n원:교실 환기 및 소독\r\n원:학생 위생수칙 교육\r\n원:필요시 보건소에 전화로 알림(정보공유)')))
    학교감염병2단계버튼 = 버튼(지역프레임, 200, 100, '아이콘\\가이드탭\\학교감염병\\학교감염병2단계.PNG', (lambda : 기본.마크다운응용('제목:학교감염병 2단계\r\n네모:의료기관에서 진단(의심) 환자 1명 발생\r\n네모:감염병 환자 추가 발생 파악(누적 2명 이상) → 유행의심기준 충족 → 학교감염병 3단계\r\n\r\n네모:감염병 환자 발생\r\n원:신고가 필요한 법정감염병인 경우 보건소에 신고\r\n원:감염병 환자 발생 사실을 학교장에게 보고\r\n원:나이스(NEIS)로 교육(지원)청에 보고\r\n\r\n네모: 신고가 필요한 법정감염병\r\n원:콜레라, 장티푸스, 파라티푸스, 세균성이질, 장출혈성 대장균 감염증, A형간염, 홍역, 결핵\r\n원:법적 근거 : ｢감염병의 예방 및 관리에 관한 법률｣ 제12조 및 시행규칙 제8조\r\n\r\n네모:유행의심여부 판단\r\n원: 학교 자체적으로 감염병 유행 여부를 판단하는 것보다 보건소의 역학조사 결과에 따르는 것이 바람직함\r\n원:다만, 학교에서는 감염병 확산의 선제적 대응을 위해 ‘유행의심 기준’에 따라 판단하고 이에 해당하면 실제 유행 여부가 불확실하더라도 대응 제3단계의 활동 수행\r\n\r\n네모:유행의심기준\r\n원:최대 잠복기 이내에 동일 학급에서 의심 또는 확진 환자 2명 이상 발생한 경우\r\n원:최초 환자와 동일 학급은 아니지만 추가 환자가 이동식 수업이나 급식 등 공통된 공간에 노출되어 관련성이 의심되는 경우\r\n바:사례 1 : 최초 환자와 같은 학급은 아니지만 추가 환자가 최초 환자가 발견된 당일 이동식 수업을함께 들었음이 확인되면 유행의심 기준을 충족함\r\n바:사례 2 : 서로 다른 학급 학생인 2명의 (의심)환자가 증상 발생 하루 전 학교 구내 매점에서 김밥을 먹은 것으로 확인 되면 유행의심 기준을 충족함\r\n\r\n네모:추가 업무\r\n원:해당 집단 능동감시 체계 실시\r\n원:밀접접촉자 파악 및 관리\r\n원:사전 사례조사 실시(설사/호흡기 역학자료 서식 있음)\r\n원:예방교육 실시\r\n\r\n네모:능동감시 체계(2단계)\r\n원:감염병 환자가 발생한 학급이 있는 동일한 층의 학급\r\n원:이동식 수업 시 감염병 환자와 함께 수업을 들은 학생들 전원\r\n원:수인성 및 식품매개 감염병의 경우 환자와 같은 음식을 먹은 학생 전체\r\n\r\n네모:밀접 접촉자\r\n원:감염병 마다 기준이 다름\r\n원:일반적 기준\r\n바:2M 이내에서 접촉\r\n바:15분 이상 함께 머문 경우\r\n바:환기가 부족한 실내, 밀폐된 공간에서 접촉\r\n바:직접적인 접촉(악수, 포옹 등) 또는 환자의 분비물에 노출(기침, 재채기, 침 등)\r\n바:마스크를 쓰지 않은 상태에서 접촉하면 밀접 접촉자로 분류될 가능성이 큼')))
    학교감염병3단계버튼 = 버튼(지역프레임, 400, 100, '아이콘\\가이드탭\\학교감염병\\학교감염병3단계.PNG', (lambda : 기본.마크다운응용('제목:학교감염병 3단계\r\n네모:의료기관에서 진단(의심) 환자 2명 이상 발생 및 유행의심기준 충족\r\n네모:유행의심 상황과 환자발생 현황을 학교장, 교육청, 보건소에 보고\r\n네모:등교중지 학생의 출석 인정처리 및 수업결손 대책 마련\r\n네모:학교감염병 관리 조직 구성\r\n\r\n소제목 :감염병 능동감시 체계 전환\r\n네모:목적 : 감염병 환자를 조기에 발견하여 감염병 전파 차단\r\n네모:주요내용 : 학생 및 교직원 전체 모니터링\r\n\r\n소제목:상황 판단 회의 1차\r\n네모:목적 : 감염병 대응전략 마련\r\n네모:참가자 : 학교, 교육청, 보건소\r\n네모:주요내용\r\n바:감염병 발생 현황 및 전파 경로 분석\r\n바:방역 조치 및 학사 운영 조정 논의 등\r\n\r\n소제목:대응 1차\r\n네모:주요내용 : 1차 상황 판단 회의에 따른 대응책 실행\r\n\r\n소제목:상황 판단 회의 2차\r\n네모:배경 : 교내 감염병 유행 지속\r\n네모:목적 : 감염병 차단을 위한 추가 조치 논의\r\n네모:참가자 : 학교, 교육청, 보건소\r\n네모:주요내용\r\n원:지역사회 확산 가능성 검토\r\n원:필요 시 학급·학교 단위 원격수업 전환\r\n\r\n소제목:대응 2차\r\n네모:주요내용\r\n원:필요 시 학급·학교 단위 원격수업 전환\r\n원:감염병 예방 교육 및 방역 강화 조치 시행\r\n\r\n소제목:학원가를 통한 추가 전파 차단\r\n네모:목적 : 지역사회 감염병 전파 차단\r\n네모:주요내용\r\n원:학원 및 다중이용시설에 대한 협조 요청\r\n원:감염 예방 수칙 안내 및 점검 강화\r\n\r\n소제목: 예방 단계 복귀\r\n네모:배경 : 마지막 (의심)환자 발생일로부터 해당 감염병의 최대 잠복기까지 추가 (의심) 환자가 발생하지 않는 경우 (예방단계로 전환)\r\n네모:주요내용 : 지속적인 감염병 감시 및 재발 방지 대책 마련')))
    학교감염병수동감시버튼 = 버튼(지역프레임, 0, 200, '아이콘\\가이드탭\\학교감염병\\학교감염병수동감시.PNG', (lambda : 기본.마크다운응용('제목:수동감시\r\n네모:감염병 환자가 발견되기를 기다리는 방식\r\n원:별도의 조사가 아니라 일상적인 관찰 속에서 감염병 환자를 발견\r\n원:학생이 병원 진료 후 감염병 확진을 받으면 학교에 보고\r\n\r\n네모:예방단계와 대응1단계에서는 수동감시체계를 사용합니다.\r\n원:해석 : 병원에서 최초의 감염병 환자를 진단하기 전에는 그냥 일상적인 관찰 속에서 아픈 학생들이 있는지 관찰하는 수준이면 됩니다.')))
