def 각종날짜입력창():
    지역프레임 = 우측새탭(창, 330, 200, 300, 850)
    각날날짜검색버튼 = 버튼(지역프레임, 0, 50, '아이콘\\편리탭\\각날\\각날날짜검색.PNG', (lambda : 기본.날짜검색(1)))
    각날날짜검색블랙버튼 = 버튼(지역프레임, 100, 50, '아이콘\\편리탭\\각날\\각날날짜검색블랙.PNG', (lambda : 기본.날짜검색(2)))
    각날이전버튼 = 버튼(지역프레임, 200, 50, '아이콘\\편리탭\\각날\\각날이전.PNG', (lambda : 기본.정규표현식반대('([0-9]+\\.\\\\b[0-9]+\\.\\\\b[0-9]+\\.)|([0-9]+\\.\\\\b[0-9]+\\.)|([0-9]+년)|([0-9]+월)|([0-9]+일)')))
    각날다음버튼 = 버튼(지역프레임, 250, 50, '아이콘\\편리탭\\각날\\각날다음.PNG', (lambda : 기본.정규표현식('([0-9]+\\.\\\\b[0-9]+\\.\\\\b[0-9]+\\.)|([0-9]+\\.\\\\b[0-9]+\\.)|([0-9]+년)|([0-9]+월)|([0-9]+일)')))
    오늘 = None()
    내일 = None + timedelta(days = 1)
    어제 = None - timedelta(days = 1)
    이번주월 = 오늘 - timedelta(오늘.weekday())
    이번주금 = 오늘 + timedelta(4 - 오늘.weekday())
    다음주월 = 오늘 + timedelta(7 - 오늘.weekday())
    다음주금 = 오늘 + timedelta(11 - 오늘.weekday())
    저번주월 = 오늘 - timedelta(7 + 오늘.weekday())
    저번주금 = 오늘 - timedelta(3 + 오늘.weekday())
    이번달초 = datetime(오늘.year, 오늘.month, 1)
    if 오늘.month == 12:
        다음달말 = datetime(오늘.year + 1, 1, 31)
    elif 오늘.month == 11:
        다음달말 = datetime(오늘.year, 12, 31)
    else:
        다음달말 = datetime(오늘.year, 오늘.month + 2, 1) - timedelta(1)
    지난달말 = datetime(오늘.year, 오늘.month, 1) - timedelta(1)
    올해초 = datetime(오늘.year, 1, 1)
    올해말 = datetime(오늘.year, 12, 31)
    내년초 = datetime(오늘.year + 1, 1, 1)
    내년말 = datetime(오늘.year + 1, 12, 31)
    작년초 = datetime(오늘.year - 1, 1, 1)
    작년말 = datetime(오늘.year - 1, 12, 31)
    임시요일 = [
        '월',
        '화',
        '수',
        '목',
        '금',
        '토',
        '일']
    if (lambda : 기본.문장(str(오늘.year) + '년 ' + str(오늘.month) + '월 ' + str(오늘.day) + '일')):
        각날오늘년월일버튼 = 지역프레임(0, 100, '아이콘\\편리탭\\각날\\각날년월일.PNG', (오늘,), (lambda : 기본.문장(str(오늘.year) + '년 ' + str(오늘.month) + '월 ' + str(오늘.day) + '일')))
    if (lambda : str(오늘.year) + '년 ' + str(오늘.month) + '월 ' + str(오늘.day) + '일 '(임시요일 + datetime.today[None().weekday()] + '요일')):
        각날오늘년월일요일버튼 = 지역프레임(50, 100, '아이콘\\편리탭\\각날\\각날년월일요일.PNG', (오늘, 임시요일), (lambda : str(오늘.year) + '년 ' + str(오늘.month) + '월 ' + str(오늘.day) + '일 '(임시요일 + datetime.today[None().weekday()] + '요일')))
    if (lambda : 기본.문장(str(오늘.year) + '. ' + str(오늘.month) + '. ' + str(오늘.day) + '.')):
        각날오늘점 = 지역프레임(100, 100, '아이콘\\편리탭\\각날\\각날점.PNG', (오늘,), (lambda : 기본.문장(str(오늘.year) + '. ' + str(오늘.month) + '. ' + str(오늘.day) + '.')))
    if (lambda : str(오늘.year) + '. ' + str(오늘.month) + '. ' + str(오늘.day) + '.('(임시요일 + datetime.today[None().weekday()] + ')')):
        각날오늘점요일 = 지역프레임(150, 100, '아이콘\\편리탭\\각날\\각날점요일.PNG', (오늘, 임시요일), (lambda : str(오늘.year) + '. ' + str(오늘.month) + '. ' + str(오늘.day) + '.('(임시요일 + datetime.today[None().weekday()] + ')')))
    if (lambda : 기본.문장("'" + str(오늘.year)[2:4] + '. ' + str(오늘.month) + '. ' + str(오늘.day) + '.')):
        각날오늘축약 = 지역프레임(200, 100, '아이콘\\편리탭\\각날\\각날축약.PNG', (오늘,), (lambda : 기본.문장("'" + str(오늘.year)[2:4] + '. ' + str(오늘.month) + '. ' + str(오늘.day) + '.')))
    if (lambda : "'" + str(오늘.year)[2:4] + '. ' + str(오늘.month) + '. ' + str(오늘.day) + '.('(임시요일 + datetime.today[None().weekday()] + ')')):
        각날오늘축약요일 = 지역프레임(250, 100, '아이콘\\편리탭\\각날\\각날축약요일.PNG', (오늘, 임시요일), (lambda : "'" + str(오늘.year)[2:4] + '. ' + str(오늘.month) + '. ' + str(오늘.day) + '.('(임시요일 + datetime.today[None().weekday()] + ')')))
    if (lambda : 기본.문장(str(내일.year) + '년 ' + str(내일.month) + '월 ' + str(내일.day) + '일')):
        각날내일년월일버튼 = 지역프레임(0, 200, '아이콘\\편리탭\\각날\\각날내일.PNG', (내일,), (lambda : 기본.문장(str(내일.year) + '년 ' + str(내일.month) + '월 ' + str(내일.day) + '일')))
    if (lambda : 기본.문장(str(내일.year) + '년 ' + str(내일.month) + '월 ' + str(내일.day) + '일 ' + 임시요일[내일.weekday()] + '요일')):
        각날내일년월일요일버튼 = 지역프레임(50, 200, '아이콘\\편리탭\\각날\\각날내일.PNG', (내일, 임시요일), (lambda : 기본.문장(str(내일.year) + '년 ' + str(내일.month) + '월 ' + str(내일.day) + '일 ' + 임시요일[내일.weekday()] + '요일')))
    if (lambda : 기본.문장(str(내일.year) + '. ' + str(내일.month) + '. ' + str(내일.day) + '.')):
        각날내일점 = 지역프레임(100, 200, '아이콘\\편리탭\\각날\\각날내일.PNG', (내일,), (lambda : 기본.문장(str(내일.year) + '. ' + str(내일.month) + '. ' + str(내일.day) + '.')))
